import type { SupportedLocale } from "@/i18n/config";
import type { LocaleFollowup } from "@/i18n/dictionaries/locale-quality-followup";

const c = (description: string, howTo: string, formula: string, exampleNote: string, question: string, answer: string) => ({
  description, howTo, formula, exampleNote, faq: { question, answer },
});

// Directly authored locale copy for three Philippine payroll tools. The copy
// describes the implemented arithmetic and clearly separates it from a payroll ruling.
export const philippinesPayrollFollowups: Partial<Record<SupportedLocale, LocaleFollowup>> = {
  ko: {
    "philippines-philhealth-calculator": c("필리핀 PhilHealth 계산기는 월 기본급을 바닥·상한에 맞춘 뒤 전체 보험료와 근로자·고용주 부담분을 계산합니다. 기준은 2025년 직접가입자 고시이며, 다른 가입 범주의 자격판정기는 아닙니다.", "PHP 기준 월 기본급을 입력하세요. 이 엔진은 PHP10,000 미만을 PHP10,000으로, PHP100,000 초과를 PHP100,000으로 조정합니다. 수수료·초과근무·수당은 기본급 입력에 섞지 마세요.", "기준급여 = min(100,000, max(10,000, 입력 기본급)); 총 보험료 = 기준급여 × 5%; 각 부담분 = 총 보험료 ÷ 2. 계산기는 소수 둘째 자리까지 결과를 반올림합니다.", "월 기본급 PHP30,000이면 총액은 PHP1,500, 근로자와 고용주 몫은 각각 PHP750입니다. 이 예시는 2025 직접가입자 요율을 대입한 산술 결과입니다.", "초과근무나 수당도 계산 기준에 포함되나요?", "아니요. PhilHealth 2025 고시는 고정 월 기본급을 사용하며 초과근무, 수수료, 수당, 13개월 급여, 보너스 등을 제외하도록 안내합니다. 가입 범주별 예외는 별도 확인하세요."),
    "philippines-pagibig-calculator": c("Pag-IBIG 계산기는 월 보수에서 엔진의 Fund Salary를 PHP10,000으로 제한하고, 근로자와 고용주 저축액을 따로 표시합니다. 2024년 2월 이후 기준으로 설명하되 가입 형태별 예외를 판정하지 않습니다.", "PHP 월 보수를 입력하세요. 2024년 2월부터의 일반 요율을 참고하는 계산이며, 본인 부담률은 Fund Salary가 PHP1,500 이하인지 초과하는지에 따라 달라집니다.", "Fund Salary = min(월 보수, PHP10,000); 근로자 = 기준액 × (기준액이 PHP1,500 이하이면 1%, 초과이면 2%); 고용주 = 기준액 × 2%; 합계 = 두 금액의 합.", "월 보수 PHP30,000이면 기준액은 PHP10,000으로 제한되어 근로자 PHP200, 고용주 PHP200, 합계 PHP400입니다. 이는 일반 요율의 산술 예시입니다.", "고용주 부담분도 급여에서 공제되나요?", "아니요. 일반적인 고용주 counterpart는 고용주 부담분이며 근로자 몫으로 더하면 안 됩니다. 자영업·임의가입 등은 부담 방식이 다를 수 있으므로 Fund 지침을 확인하세요."),
    "philippines-gross-net-salary-calculator": c("필리핀 세전·세후 급여 계산기는 입력 급여와 연간/월간 선택에 따라 연간 세금과 일부 근로자 부담금을 추정합니다. 급여명세서나 BIR 원천징수 계산을 대체하지 않습니다.", "총급여 PHP와 지급 주기를 입력하세요. 월간은 연간 급여로 환산해 누진세를 계산합니다. 공제 대상 급여 구성, 부양가족, 13개월 급여, 과세·비과세 수당 입력은 제공하지 않습니다.", "연간 총급여 = 월 입력이면 급여×12, 아니면 연간 입력값. 세금은 계산기 내 연간 누진 구간으로 산출합니다. 직원 부담금은 입력값에 SSS 5%·PHP35,000 상한과 PhilHealth 2.5%·PHP100,000 상한을 적용해 연환산합니다. Pag-IBIG는 포함하지 않습니다.", "월 PHP60,000을 입력하면 엔진은 연간 총액 PHP720,000, 추정 세금 PHP86,500, 연간 직원 부담금 PHP39,000, 연간 순액 PHP594,500 및 월 환산 PHP49,541.67을 반환합니다. 이 숫자는 엔진 예시이지 실제 급여 공제가 아닙니다.", "왜 결과가 급여명세서와 다를 수 있나요?", "지급 주기별 원천징수 표, 과세·비과세 항목, 공제·세액공제, Pag-IBIG, SSS 급여구간·EC·MPF가 모두 반영되지 않습니다. 특히 연간 입력에서는 기여금 기준을 월급으로 해석하는 한계가 있어 월간 입력 예시 외의 payroll 정확도는 보장하지 않습니다."),
  },
  en: {
    "philippines-philhealth-calculator": c("This Philippine PhilHealth tool floors and caps monthly basic salary, then splits the computed premium equally between employee and employer. Its reference is the 2025 Direct Contributor advisory; it does not determine other membership categories.", "Enter monthly basic salary in PHP. The engine uses PHP10,000 below the floor and PHP100,000 above the ceiling. Do not add overtime, commissions, or allowances to the basic-salary input.", "Basis = min(100,000, max(10,000, monthly basic salary)); total premium = basis × 5%; each share = total ÷ 2. Displayed results are rounded to two decimal places.", "At PHP30,000 monthly basic salary, total premium is PHP1,500, split into PHP750 for the employee and PHP750 for the employer. This is arithmetic under the 2025 Direct Contributor schedule.", "Are overtime and allowances part of the contribution base?", "The 2025 advisory defines monthly basic salary and excludes commissions, overtime, allowances, 13th-month pay, bonuses, and similar items. Eligibility and special member categories require separate review."),
    "philippines-pagibig-calculator": c("The Pag-IBIG calculator caps monthly Fund Salary at PHP10,000 and shows employee and employer savings separately. The explanation reflects the increase effective February 2024; it does not classify membership exceptions.", "Enter monthly compensation in PHP. Under the general schedule, the employee rate depends on whether Fund Salary is at or below PHP1,500; the employer counterpart is shown separately.", "Fund Salary = min(monthly compensation, PHP10,000); employee = base × 1% when base ≤ PHP1,500, otherwise 2%; employer = base × 2%; total = both shares.", "At PHP30,000 monthly compensation, the engine caps the base at PHP10,000 and returns PHP200 employee, PHP200 employer, PHP400 total. This illustrates the general rates.", "Is the employer share deducted from my pay?", "No. The ordinary employer counterpart is the employer's share and should not be added to the employee deduction. Self-employed and voluntary members may have different payment responsibilities; check Fund guidance."),
    "philippines-gross-net-salary-calculator": c("This Philippine gross-to-net tool estimates annual tax and selected employee contributions from gross pay and an annual or monthly period choice. It is not a payroll statement or BIR withholding calculation.", "Enter gross PHP pay and select annual or monthly. Monthly pay is annualized for the progressive tax estimate. The form does not collect taxable and exempt pay components, deductions, dependants, or 13th-month benefit details.", "Annual gross = monthly input × 12, otherwise the annual input. Tax uses the calculator's annual progressive bands. Employee contributions annualize the entered amount using the engine's SSS 5% base capped at PHP35,000 and PhilHealth 2.5% base capped at PHP100,000. Pag-IBIG is omitted.", "For PHP60,000 monthly pay, the engine returns PHP720,000 annual gross, PHP86,500 estimated tax, PHP39,000 annual employee contributions, PHP594,500 annual net, and PHP49,541.67 monthly equivalent. These are engine outputs, not a payroll deduction result.", "Why can this differ from a payslip?", "The model omits payroll-period withholding tables, taxable/exempt compensation details, deductions and credits, Pag-IBIG, and SSS salary-credit, EC, and MPF amounts. Its annual-input contribution treatment also has a monthly-base limitation, so payroll accuracy is not established."),
  },
  ja: {
    "philippines-philhealth-calculator": c("フィリピンPhilHealthの計算では、月額基本給に下限・上限を適用して保険料を求め、従業員と雇用主に半分ずつ分けます。根拠として示すのは2025年の直接加入者向け告知で、他の加入区分の判定はしません。", "PHPの月額基本給を入力します。エンジンはPHP10,000未満を下限、PHP100,000超を上限として扱います。残業代、歩合、手当を基本給に加えないでください。", "基準額=min(100,000, max(10,000, 月額基本給)); 保険料合計=基準額×5%; 各負担額=合計÷2。表示値は小数第2位に丸めます。", "月額基本給がPHP30,000なら保険料合計はPHP1,500、従業員と雇用主は各PHP750です。2025年の直接加入者向け条件を用いた計算例です。", "残業代や手当も基準に入りますか？", "2025年告知の月額基本給には、歩合、残業代、手当、13か月給与、賞与などを含めません。加入区分や個別の適用条件は別途確認してください。"),
    "philippines-pagibig-calculator": c("Pag-IBIG計算機は月額報酬にPHP10,000のFund Salary上限を適用し、従業員分と雇用主分を分けて表示します。2024年2月以降の基準を説明しますが、加入形態の例外判定はしません。", "PHPの月額報酬を入力します。一般的な率ではFund SalaryがPHP1,500以下か超えるかで従業員率が変わり、雇用主分は別表示されます。", "Fund Salary=min(月額報酬, PHP10,000); 従業員分=基準額×(1,500以下なら1%、超なら2%); 雇用主分=基準額×2%; 合計=両者の和。", "月額報酬PHP30,000では基準額がPHP10,000となり、従業員PHP200、雇用主PHP200、合計PHP400です。一般率の計算例です。", "雇用主分も給与から差し引かれますか？", "通常、雇用主分は雇用主側の負担であり、従業員控除に加えません。自営業者や任意加入者などは負担方法が異なる場合があるため公式案内を確認してください。"),
    "philippines-gross-net-salary-calculator": c("フィリピンの手取り計算機は、総支給額と年額・月額の選択から年間税額と一部の従業員負担を推定します。給与明細やBIRの源泉徴収計算の代わりにはなりません。", "PHPの総支給額と年額または月額を入力します。月額は年額に換算して累進税を計算します。課税・非課税項目、控除、扶養、13か月給与は入力できません。", "年額総支給=月額入力×12、または年額入力。税は計算機内の年次累進税率で算出。従業員負担は入力値からSSS 5%(基礎上限PHP35,000)とPhilHealth 2.5%(PHP100,000上限)を年換算します。Pag-IBIGは含みません。", "月額PHP60,000では年額総支給PHP720,000、推定税PHP86,500、年換算従業員負担PHP39,000、年手取りPHP594,500、月換算PHP49,541.67です。実際の給与控除額ではなくエンジンの例です。", "給与明細と結果が異なるのはなぜですか？", "給与期間別源泉徴収表、課税・非課税給与、控除・税額控除、Pag-IBIG、SSSの給与クレジット区分・EC・MPFを扱いません。年額入力時の拠出金計算にも月額基礎の制約があり、給与計算の正確性は保証されません。"),
  },
  zh: {
    "philippines-philhealth-calculator": c("菲律宾 PhilHealth 计算器先对月基本工资应用下限和上限，再计算保费并由雇员与雇主各承担一半。说明依据为2025年直接缴费成员公告，不判断其他会员类别。", "输入 PHP 月基本工资。引擎将低于 PHP10,000 的基数按 PHP10,000 计算，高于 PHP100,000 的按 PHP100,000 计算。不要把加班费、佣金或津贴并入基本工资。", "基数=min(100,000, max(10,000, 月基本工资)); 总保费=基数×5%; 双方各付总额的一半。显示结果四舍五入到小数点后两位。", "月基本工资 PHP30,000 时，总保费 PHP1,500，雇员和雇主各 PHP750。这是按2025年直接缴费成员参数进行的算术示例。", "加班费和津贴也计入基数吗？", "2025年公告所称月基本工资不包括佣金、加班费、津贴、第13个月工资、奖金等。会员类别和个别适用条件需另行核实。"),
    "philippines-pagibig-calculator": c("Pag-IBIG 计算器将月报酬基数上限设为 PHP10,000，并分别显示雇员和雇主储蓄额。说明采用2024年2月起的基准，不判定会员例外。", "输入 PHP 月报酬。一般费率下，Fund Salary 不超过 PHP1,500 时雇员费率不同；雇主份额单独显示。", "Fund Salary=min(月报酬, PHP10,000); 雇员=基数×(不超过1,500时1%，超过时2%); 雇主=基数×2%; 合计为双方之和。", "月报酬 PHP30,000 时，基数封顶 PHP10,000，结果为雇员 PHP200、雇主 PHP200、合计 PHP400。这是一般费率示例。", "雇主份额会从我的工资中扣除吗？", "通常不会。雇主配缴是雇主承担的部分，不应加到雇员扣款里。自雇或自愿会员的缴费责任可能不同，请查阅基金说明。"),
    "philippines-gross-net-salary-calculator": c("菲律宾税前税后工资工具根据总工资和年/月周期选项估算年度所得税及部分雇员缴费，不是工资单或BIR工资预扣税计算器。", "输入 PHP 总工资并选择年薪或月薪。月薪会年化后用于累进税估算。表单不收集应税/免税工资构成、扣除额、受扶养人或第13个月工资信息。", "年总工资=月薪输入×12，否则使用年薪输入。所得税按工具内的年度累进档计算。雇员缴费按输入值估算 SSS 5%(基数上限PHP35,000)和 PhilHealth 2.5%(PHP100,000上限)，再年化；不含Pag-IBIG。", "月薪 PHP60,000 时，结果为年总工资 PHP720,000、估算税额 PHP86,500、年度雇员缴费 PHP39,000、年净额 PHP594,500、月均 PHP49,541.67。这只是引擎输出，不是实际工资扣款。", "为什么结果和工资单不同？", "本模型没有按发薪周期处理预扣税表、应税/免税项目、扣除与抵免、Pag-IBIG，也没有SSS工资信用档、EC和MPF。年薪输入下的缴费基数处理也有月度基数限制，因此不能保证工资核算准确。"),
  },
  "zh-tw": {
    "philippines-philhealth-calculator": c("菲律賓 PhilHealth 計算器先對月基本薪資套用下限與上限，再計算保費並由員工和雇主各負擔一半。說明依據為2025年直接繳費會員公告，不判定其他會員類別。", "輸入 PHP 月基本薪資。引擎將低於 PHP10,000 的基數按 PHP10,000 計算，高於 PHP100,000 的按 PHP100,000 計算。加班費、佣金或津貼不要併入基本薪資。", "基數=min(100,000, max(10,000, 月基本薪資)); 總保費=基數×5%; 雙方各負擔總額的一半。顯示結果四捨五入至小數點後兩位。", "月基本薪資 PHP30,000 時，總保費 PHP1,500，員工與雇主各 PHP750。這是依2025年直接繳費會員條件計算的示例。", "加班費和津貼也計入基數嗎？", "2025年公告所稱月基本薪資不包括佣金、加班費、津貼、第13個月薪資、獎金等。會員類別和個別適用條件需另行確認。"),
    "philippines-pagibig-calculator": c("Pag-IBIG 計算器將月報酬基數上限設為 PHP10,000，並分別顯示員工與雇主儲蓄額。說明採用2024年2月起的基準，不判定會員例外。", "輸入 PHP 月報酬。一般費率下，Fund Salary 不超過 PHP1,500 時員工費率不同；雇主份額另行顯示。", "Fund Salary=min(月報酬, PHP10,000); 員工=基數×(不超過1,500時1%，超過時2%); 雇主=基數×2%; 合計為雙方之和。", "月報酬 PHP30,000 時，基數上限為 PHP10,000，結果是員工 PHP200、雇主 PHP200、合計 PHP400。這是一般費率示例。", "雇主份額會從我的薪資扣除嗎？", "一般不會。雇主配繳是雇主負擔，不應加到員工扣款。自營或自願會員的繳費責任可能不同，請查閱基金說明。"),
    "philippines-gross-net-salary-calculator": c("菲律賓稅前稅後薪資工具依總薪資與年/月週期選項估算年度所得稅及部分員工繳費，不是薪資單或BIR薪資預扣稅計算器。", "輸入 PHP 總薪資並選擇年薪或月薪。月薪會年化後用於累進稅估算。表單不收集應稅/免稅薪資組成、扣除額、扶養人或第13個月薪資資訊。", "年總薪資=月薪輸入×12，否則使用年薪輸入。所得稅按工具內年度累進級距計算。員工繳費依輸入值估算 SSS 5%(基數上限PHP35,000)及 PhilHealth 2.5%(PHP100,000上限)，再年化；不含Pag-IBIG。", "月薪 PHP60,000 時，結果為年總薪資 PHP720,000、估算稅額 PHP86,500、年度員工繳費 PHP39,000、年淨額 PHP594,500、月均 PHP49,541.67。這只是引擎輸出，不是實際薪資扣款。", "為什麼結果和薪資單不同？", "模型沒有依發薪週期處理預扣稅表、應稅/免稅項目、扣除與抵免、Pag-IBIG，也沒有SSS薪資信用級距、EC和MPF。年薪輸入下的繳費基數處理也受月基數限制，不能保證薪資核算準確。"),
  },
  es: {
    "philippines-philhealth-calculator": c("Esta herramienta de PhilHealth aplica un mínimo y un máximo al salario básico mensual y divide la prima entre empleado y empleador. La referencia indicada es el aviso de 2025 para contribuyentes directos; no determina otras categorías de afiliación.", "Introduce el salario básico mensual en PHP. El motor usa PHP10.000 como mínimo y PHP100.000 como máximo. No añadas horas extra, comisiones ni complementos al salario básico.", "Base=min(100.000, max(10.000, salario básico mensual)); prima total=base×5%; cada parte=prima total÷2. Los resultados se redondean a dos decimales.", "Con PHP30.000 de salario básico mensual, la prima total es PHP1.500: PHP750 para el empleado y PHP750 para el empleador. Es un ejemplo aritmético según el aviso de 2025.", "¿Se incluyen las horas extra y los complementos?", "El aviso de 2025 excluye del salario básico las comisiones, horas extra, asignaciones, paga del decimotercer mes, bonificaciones y conceptos similares. Comprueba por separado las condiciones de cada categoría de afiliación."),
    "philippines-pagibig-calculator": c("La calculadora Pag-IBIG limita la base salarial mensual a PHP10.000 y muestra por separado el ahorro del empleado y del empleador. La explicación usa el límite vigente desde febrero de 2024 y no determina excepciones de afiliación.", "Introduce la remuneración mensual en PHP. Con las tasas generales, la aportación del empleado depende de si la base supera PHP1.500; la parte patronal aparece por separado.", "Fund Salary=min(remuneración mensual, PHP10.000); empleado=base×1% si es ≤1.500, o 2% si es mayor; empleador=base×2%; total=suma de ambas partes.", "Con PHP30.000 al mes, la base se limita a PHP10.000 y el motor muestra PHP200 del empleado, PHP200 del empleador y PHP400 en total. Es un ejemplo de las tasas generales.", "¿La parte del empleador se descuenta de mi salario?", "No. La aportación ordinaria del empleador es su propia parte y no debe sumarse a la deducción del trabajador. Autónomos y afiliados voluntarios pueden tener otras obligaciones; consulta la guía del Fondo."),
    "philippines-gross-net-salary-calculator": c("Esta herramienta estima el impuesto anual y algunas aportaciones del empleado a partir del salario bruto y de la opción anual o mensual. No sustituye una nómina ni el cálculo de retención de BIR.", "Introduce el salario bruto en PHP y elige periodo anual o mensual. El salario mensual se anualiza para estimar el impuesto progresivo. No se solicitan conceptos sujetos o exentos, deducciones, dependientes ni datos de la paga del decimotercer mes.", "Salario bruto anual=entrada mensual×12, o entrada anual. El impuesto usa los tramos anuales del motor. Las aportaciones del empleado anualizan SSS 5%(base limitada a PHP35.000) y PhilHealth 2,5%(límite PHP100.000); Pag-IBIG queda fuera.", "Con PHP60.000 mensuales, el motor devuelve PHP720.000 de bruto anual, PHP86.500 de impuesto estimado, PHP39.000 de aportaciones anuales, PHP594.500 netos al año y PHP49.541,67 al mes. Es una salida del motor, no una deducción de nómina real.", "¿Por qué puede diferir de mi nómina?", "No aplica tablas de retención por periodo ni clasifica conceptos gravables/exentos, deducciones o créditos; también omite Pag-IBIG y los tramos salariales, EC y MPF de SSS. El tratamiento de aportaciones cuando se introduce un salario anual tiene además una limitación de base mensual, así que no se garantiza precisión de nómina."),
  },
  "pt-br": {
    "philippines-philhealth-calculator": c("Esta ferramenta da PhilHealth aplica piso e teto ao salário básico mensal e divide o prêmio igualmente entre empregado e empregador. A referência é o aviso de 2025 para contribuintes diretos; ela não classifica outras categorias de membros.", "Informe o salário básico mensal em PHP. O mecanismo usa PHP10.000 como piso e PHP100.000 como teto. Não some horas extras, comissões ou adicionais ao salário básico.", "Base=min(100.000, max(10.000, salário básico mensal)); prêmio total=base×5%; cada parte=total÷2. Os resultados são arredondados para duas casas decimais.", "Com salário básico mensal de PHP30.000, o prêmio total é PHP1.500, dividido em PHP750 para o empregado e PHP750 para o empregador. É um exemplo aritmético conforme o aviso de 2025.", "Horas extras e adicionais entram na base?", "O aviso de 2025 exclui comissões, horas extras, adicionais, 13º salário, bônus e itens semelhantes do salário básico mensal. Verifique separadamente as condições de cada categoria de membro."),
    "philippines-pagibig-calculator": c("A calculadora Pag-IBIG limita a base salarial mensal a PHP10.000 e mostra separadamente a poupança do empregado e do empregador. A explicação considera o limite efetivo desde fevereiro de 2024 e não classifica exceções de filiação.", "Informe a remuneração mensal em PHP. Nas taxas gerais, a parcela do empregado depende de a base ser até PHP1.500 ou superior; a parcela patronal aparece separadamente.", "Fund Salary=min(remuneração mensal, PHP10.000); empregado=base×1% se ≤1.500 ou 2% se maior; empregador=base×2%; total=soma das parcelas.", "Com PHP30.000 mensais, a base fica limitada a PHP10.000 e o mecanismo mostra PHP200 do empregado, PHP200 do empregador e PHP400 no total. É um exemplo das taxas gerais.", "A parcela do empregador é descontada do meu salário?", "Não. A contrapartida normal do empregador é responsabilidade dele e não deve ser somada ao desconto do empregado. Autônomos e membros voluntários podem ter outras obrigações; consulte as orientações do Fundo."),
    "philippines-gross-net-salary-calculator": c("A ferramenta estima imposto anual e algumas contribuições do empregado a partir do salário bruto e da opção anual ou mensal. Não substitui holerite nem cálculo de retenção da BIR.", "Informe o salário bruto em PHP e escolha anual ou mensal. A entrada mensal é anualizada para estimar o imposto progressivo. O formulário não coleta itens tributáveis/isentos, deduções, dependentes ou dados do 13º salário.", "Salário bruto anual=entrada mensal×12 ou entrada anual. O imposto usa as faixas anuais do motor. As contribuições anualizam SSS 5%(base limitada a PHP35.000) e PhilHealth 2,5%(teto PHP100.000); Pag-IBIG não é incluído.", "Com PHP60.000 mensais, o motor retorna bruto anual PHP720.000, imposto estimado PHP86.500, contribuições anuais PHP39.000, líquido anual PHP594.500 e equivalente mensal PHP49.541,67. É uma saída do motor, não uma dedução real de folha.", "Por que o resultado pode diferir do holerite?", "O modelo não usa tabelas de retenção por período, não classifica remuneração tributável/isenta, deduções ou créditos e omite Pag-IBIG, faixas salariais SSS, EC e MPF. O tratamento de contribuições na entrada anual também tem limite de base mensal; portanto, não há garantia de precisão para folha."),
  },
  de: {
    "philippines-philhealth-calculator": c("Der PhilHealth-Rechner setzt für das Monatsgrundgehalt eine Unter- und Obergrenze an und teilt den Beitrag gleichmäßig zwischen Arbeitnehmer und Arbeitgeber. Als Bezug dient der Hinweis 2025 für Direct Contributors; andere Mitgliedskategorien werden nicht bestimmt.", "Geben Sie das monatliche Grundgehalt in PHP ein. Die Engine verwendet mindestens PHP10.000 und höchstens PHP100.000. Überstunden, Provisionen und Zulagen gehören nicht in die Grundgehaltsangabe.", "Bemessungsgrundlage=min(100.000, max(10.000, Monatsgrundgehalt)); Gesamtbeitrag=Basis×5%; jeder Anteil=Gesamt÷2. Die Anzeige rundet auf zwei Dezimalstellen.", "Bei PHP30.000 Monatsgrundgehalt beträgt der Gesamtbeitrag PHP1.500, davon je PHP750 für Arbeitnehmer und Arbeitgeber. Das ist ein Rechenbeispiel nach dem Hinweis für 2025.", "Zählen Überstunden und Zulagen zur Basis?", "Der Hinweis 2025 schließt Provisionen, Überstunden, Zulagen, 13. Monatsgehalt, Boni und ähnliche Zahlungen aus dem Monatsgrundgehalt aus. Mitgliedskategorie und individuelle Voraussetzungen sind separat zu prüfen."),
    "philippines-pagibig-calculator": c("Der Pag-IBIG-Rechner begrenzt das monatliche Fund Salary auf PHP10.000 und zeigt Arbeitnehmer- und Arbeitgeberanteil getrennt. Die Erläuterung berücksichtigt die Erhöhung ab Februar 2024, bewertet aber keine Mitgliedsausnahmen.", "Geben Sie das Monatsentgelt in PHP ein. Beim allgemeinen Satz hängt der Arbeitnehmeranteil davon ab, ob die Basis höchstens PHP1.500 beträgt; der Arbeitgeberanteil wird separat ausgewiesen.", "Fund Salary=min(Monatsentgelt, PHP10.000); Arbeitnehmer=Basis×1% bei höchstens 1.500, sonst 2%; Arbeitgeber=Basis×2%; Gesamt=summe beider Anteile.", "Bei PHP30.000 Monatsentgelt wird die Basis auf PHP10.000 begrenzt: PHP200 Arbeitnehmer, PHP200 Arbeitgeber, PHP400 insgesamt. Das veranschaulicht die allgemeinen Sätze.", "Wird der Arbeitgeberanteil vom Gehalt abgezogen?", "Nein. Der übliche Arbeitgeberanteil ist dessen eigener Beitrag und darf nicht zur Arbeitnehmerabgabe addiert werden. Selbständige und freiwillige Mitglieder können anders einzahlen; prüfen Sie die Hinweise des Fonds."),
    "philippines-gross-net-salary-calculator": c("Dieses Philippinen-Tool schätzt aus Bruttogehalt und Jahres- oder Monatsauswahl die Jahressteuer und ausgewählte Arbeitnehmerbeiträge. Es ersetzt weder eine Gehaltsabrechnung noch die BIR-Lohnsteuerberechnung.", "Geben Sie das Bruttogehalt in PHP ein und wählen Sie jährlich oder monatlich. Monatsgehalt wird für die progressive Steuerschätzung annualisiert. Steuerfreie/steuerpflichtige Bestandteile, Abzüge, Angehörige und 13. Monatsgehalt werden nicht abgefragt.", "Jahresbrutto=Monatseingabe×12, sonst Jahreseingabe. Die Steuer nutzt die jährlichen Progressionsstufen der Engine. Arbeitnehmerbeiträge werden mit SSS 5%(Basisdeckel PHP35.000) und PhilHealth 2,5%(Deckel PHP100.000) annualisiert; Pag-IBIG fehlt.", "Bei PHP60.000 Monatsgehalt liefert die Engine PHP720.000 Jahresbrutto, PHP86.500 geschätzte Steuer, PHP39.000 Jahresbeiträge, PHP594.500 Jahresnetto und PHP49.541,67 Monatsäquivalent. Das ist ein Engine-Beispiel, kein realer Lohnabzug.", "Warum weicht das Ergebnis von der Abrechnung ab?", "Das Modell verwendet keine einheitlichen Lohnsteuer-Tabellen je Zahlungsperiode, klassifiziert keine steuerpflichtigen oder steuerfreien Bestandteile und berücksichtigt weder Abzüge/Gutschriften noch Pag-IBIG oder SSS-Gehaltskreditstufen, EC und MPF. Bei Jahresgehalt ist außerdem die monatliche Beitragsbasis eingeschränkt; eine korrekte Payroll wird nicht zugesichert."),
  },
  fr: {
    "philippines-philhealth-calculator": c("L’outil PhilHealth applique un plancher et un plafond au salaire de base mensuel, puis partage la prime à parts égales entre salarié et employeur. La référence est l’avis 2025 pour les cotisants directs ; les autres catégories ne sont pas déterminées.", "Saisissez le salaire de base mensuel en PHP. Le moteur retient au minimum PHP10 000 et au maximum PHP100 000. N’ajoutez pas les heures supplémentaires, commissions ou indemnités au salaire de base.", "Base=min(100 000, max(10 000, salaire de base mensuel)); prime totale=base×5%; chaque part=total÷2. L’affichage arrondit à deux décimales.", "Avec un salaire de base mensuel de PHP30 000, la prime totale vaut PHP1 500, soit PHP750 pour le salarié et PHP750 pour l’employeur. Exemple arithmétique selon l’avis 2025.", "Les heures supplémentaires et indemnités entrent-elles dans la base ?", "L’avis 2025 exclut du salaire de base mensuel les commissions, heures supplémentaires, indemnités, 13e mois, primes et éléments similaires. Vérifiez séparément la catégorie d’affiliation et les conditions individuelles."),
    "philippines-pagibig-calculator": c("Le calculateur Pag-IBIG plafonne le Fund Salary mensuel à PHP10 000 et distingue l’épargne du salarié de celle de l’employeur. Le texte reflète le plafond applicable depuis février 2024 sans déterminer les exceptions d’affiliation.", "Saisissez la rémunération mensuelle en PHP. Au taux général, la part du salarié dépend d’une base inférieure ou égale à PHP1 500 ou supérieure ; la part employeur apparaît séparément.", "Fund Salary=min(rémunération mensuelle, PHP10 000); salarié=base×1% si ≤1 500, sinon 2%; employeur=base×2%; total=somme des deux parts.", "Pour PHP30 000 par mois, la base est plafonnée à PHP10 000 : PHP200 salarié, PHP200 employeur, PHP400 au total. Exemple aux taux généraux.", "La part employeur est-elle retenue sur mon salaire ?", "Non. La contribution patronale ordinaire est à la charge de l’employeur et ne doit pas être ajoutée à la retenue du salarié. Les indépendants et membres volontaires peuvent relever d’autres modalités ; consultez le Fonds."),
    "philippines-gross-net-salary-calculator": c("Cet outil estime l’impôt annuel et certaines cotisations salariales à partir du brut et du choix annuel ou mensuel. Il ne remplace ni un bulletin de paie ni le calcul de retenue de BIR.", "Saisissez le salaire brut en PHP et choisissez annuel ou mensuel. Le montant mensuel est annualisé pour l’estimation progressive. Les éléments imposables/exonérés, déductions, personnes à charge et 13e mois ne sont pas saisis.", "Brut annuel=entrée mensuelle×12, sinon entrée annuelle. L’impôt suit les tranches annuelles du moteur. Les cotisations salarié annualisent SSS 5%(base plafonnée à PHP35 000) et PhilHealth 2,5%(plafond PHP100 000) ; Pag-IBIG est exclu.", "Avec PHP60 000 mensuels, le moteur renvoie PHP720 000 de brut annuel, PHP86 500 d’impôt estimé, PHP39 000 de cotisations annuelles, PHP594 500 nets annuels et PHP49 541,67 par mois. C’est un résultat moteur, pas une retenue réelle.", "Pourquoi le résultat diffère-t-il d’une fiche de paie ?", "Le modèle ne traite pas les tables de retenue selon la période de paie, ne classe pas les éléments imposables/exonérés, déductions ou crédits et omet Pag-IBIG ainsi que les tranches SSS, EC et MPF. La base de cotisation a aussi une limite lors d’une saisie annuelle ; la précision de paie n’est pas garantie."),
  },
  vi: {
    "philippines-philhealth-calculator": c("Công cụ PhilHealth áp dụng mức sàn và trần cho lương cơ bản tháng, sau đó chia phí bảo hiểm đều cho người lao động và chủ lao động. Nội dung tham chiếu thông báo năm 2025 cho Direct Contributors; không xác định các nhóm hội viên khác.", "Nhập lương cơ bản tháng bằng PHP. Engine dùng tối thiểu PHP10.000 và tối đa PHP100.000. Không cộng làm thêm, hoa hồng hoặc phụ cấp vào lương cơ bản.", "Cơ sở=min(100.000, max(10.000, lương cơ bản tháng)); tổng phí=cơ sở×5%; mỗi bên=tổng÷2. Kết quả hiển thị làm tròn hai chữ số thập phân.", "Với lương cơ bản PHP30.000/tháng, tổng phí là PHP1.500; người lao động và chủ lao động mỗi bên PHP750. Đây là ví dụ số học theo thông báo Direct Contributor năm 2025.", "Làm thêm và phụ cấp có nằm trong cơ sở không?", "Thông báo 2025 loại hoa hồng, làm thêm, phụ cấp, lương tháng thứ 13, tiền thưởng và khoản tương tự khỏi Monthly Basic Salary. Hãy kiểm tra riêng nhóm hội viên và điều kiện cá nhân."),
    "philippines-pagibig-calculator": c("Máy tính Pag-IBIG giới hạn Fund Salary tháng ở PHP10.000 và tách khoản tiết kiệm của người lao động với chủ lao động. Nội dung dùng mức áp dụng từ tháng 2/2024 và không xác định ngoại lệ thành viên.", "Nhập tiền lương tháng bằng PHP. Theo mức chung, tỷ lệ người lao động phụ thuộc cơ sở có vượt PHP1.500 hay không; phần chủ lao động được hiển thị riêng.", "Fund Salary=min(lương tháng, PHP10.000); người lao động=cơ sở×1% nếu ≤1.500, nếu cao hơn thì 2%; chủ lao động=cơ sở×2%; tổng là hai phần cộng lại.", "Với lương PHP30.000/tháng, cơ sở bị giới hạn ở PHP10.000; kết quả là PHP200 từ người lao động, PHP200 từ chủ lao động, tổng PHP400. Đây là ví dụ theo mức chung.", "Phần của chủ lao động có bị trừ vào lương tôi không?", "Không. Phần đối ứng thông thường là nghĩa vụ của chủ lao động và không nên cộng vào khoản trừ của người lao động. Người tự doanh hoặc thành viên tự nguyện có thể chịu cách đóng khác; hãy xem hướng dẫn của Quỹ."),
    "philippines-gross-net-salary-calculator": c("Công cụ ước tính thuế năm và một số khoản đóng của người lao động từ lương gộp cùng lựa chọn năm/tháng. Công cụ không thay thế phiếu lương hoặc phép tính khấu lưu của BIR.", "Nhập lương gộp PHP và chọn năm hoặc tháng. Lương tháng được quy đổi năm để ước tính thuế lũy tiến. Biểu mẫu không nhận các khoản chịu/miễn thuế, giảm trừ, người phụ thuộc hoặc chi tiết tháng lương thứ 13.", "Lương gộp năm=đầu vào tháng×12 hoặc đầu vào năm. Thuế dùng các bậc năm trong engine. Khoản người lao động được quy năm theo SSS 5%(cơ sở tối đa PHP35.000) và PhilHealth 2,5%(trần PHP100.000); không gồm Pag-IBIG.", "Với PHP60.000/tháng, engine trả lương gộp năm PHP720.000, thuế ước tính PHP86.500, khoản đóng năm PHP39.000, thực nhận năm PHP594.500 và tương đương tháng PHP49.541,67. Đây là kết quả engine, không phải khấu trừ bảng lương thực tế.", "Vì sao kết quả khác phiếu lương?", "Mô hình không áp dụng bảng khấu lưu theo kỳ trả lương, không phân loại khoản chịu/miễn thuế, giảm trừ hay tín thuế; đồng thời bỏ qua Pag-IBIG và bậc tín dụng lương SSS, EC, MPF. Cách tính khoản đóng khi nhập lương năm còn bị giới hạn bởi cơ sở tháng, nên không đảm bảo độ chính xác tiền lương."),
  },
  id: {
    "philippines-philhealth-calculator": c("Kalkulator PhilHealth menerapkan batas bawah dan atas pada gaji pokok bulanan lalu membagi premi sama rata antara pekerja dan pemberi kerja. Rujukannya adalah pemberitahuan 2025 untuk Direct Contributors; kategori anggota lain tidak ditentukan.", "Masukkan gaji pokok bulanan dalam PHP. Mesin memakai batas minimum PHP10.000 dan maksimum PHP100.000. Jangan masukkan lembur, komisi, atau tunjangan ke gaji pokok.", "Dasar=min(100.000, max(10.000, gaji pokok bulanan)); premi total=dasar×5%; tiap pihak=total÷2. Hasil ditampilkan dengan pembulatan dua desimal.", "Pada gaji pokok PHP30.000 per bulan, premi total PHP1.500, masing-masing PHP750 untuk pekerja dan pemberi kerja. Ini contoh aritmetika sesuai pemberitahuan 2025.", "Apakah lembur dan tunjangan termasuk dasar?", "Pemberitahuan 2025 mengecualikan komisi, lembur, tunjangan, gaji bulan ke-13, bonus, dan pembayaran serupa dari Monthly Basic Salary. Periksa kategori anggota dan syarat individual secara terpisah."),
    "philippines-pagibig-calculator": c("Kalkulator Pag-IBIG membatasi Fund Salary bulanan hingga PHP10.000 dan memisahkan tabungan pekerja dari bagian pemberi kerja. Penjelasan memakai batas yang berlaku sejak Februari 2024 dan tidak menentukan pengecualian keanggotaan.", "Masukkan kompensasi bulanan dalam PHP. Dalam tarif umum, bagian pekerja bergantung pada apakah dasar melebihi PHP1.500; bagian pemberi kerja ditampilkan terpisah.", "Fund Salary=min(kompensasi bulanan, PHP10.000); pekerja=dasar×1% jika ≤1.500, selain itu 2%; pemberi kerja=dasar×2%; total=jumlah kedua bagian.", "Pada kompensasi PHP30.000 per bulan, dasar dibatasi PHP10.000 dan mesin menampilkan PHP200 pekerja, PHP200 pemberi kerja, total PHP400. Ini contoh tarif umum.", "Apakah bagian pemberi kerja dipotong dari gaji saya?", "Tidak. Bagian pemberi kerja biasa merupakan tanggung jawab pemberi kerja dan tidak boleh ditambahkan ke potongan pekerja. Pekerja mandiri dan anggota sukarela dapat memiliki kewajiban berbeda; periksa panduan Fund."),
    "philippines-gross-net-salary-calculator": c("Alat ini memperkirakan pajak tahunan dan sebagian iuran pekerja dari gaji bruto serta pilihan periode tahunan atau bulanan. Ini bukan slip gaji atau kalkulasi pemotongan pajak BIR.", "Masukkan gaji bruto PHP dan pilih tahunan atau bulanan. Nilai bulanan disetahunkan untuk estimasi pajak progresif. Formulir tidak meminta komponen kena pajak/bebas pajak, pengurang, tanggungan, atau rincian gaji bulan ke-13.", "Gaji bruto tahunan=input bulanan×12 atau input tahunan. Pajak memakai lapisan tahunan di mesin. Iuran pekerja disetahunkan memakai SSS 5%(dasar maksimum PHP35.000) dan PhilHealth 2,5%(maksimum PHP100.000); Pag-IBIG tidak disertakan.", "Untuk PHP60.000 per bulan, mesin menghasilkan bruto tahunan PHP720.000, pajak estimasi PHP86.500, iuran tahunan PHP39.000, bersih tahunan PHP594.500, dan ekuivalen bulanan PHP49.541,67. Ini keluaran mesin, bukan potongan gaji aktual.", "Mengapa hasilnya bisa berbeda dari slip gaji?", "Model tidak memakai tabel pemotongan berdasarkan periode gaji, tidak mengelompokkan komponen kena pajak/bebas pajak, pengurang atau kredit, serta mengabaikan Pag-IBIG dan tingkatan kredit gaji SSS, EC, dan MPF. Input tahunan juga memiliki keterbatasan dasar iuran bulanan, sehingga akurasi penggajian tidak dijamin."),
  },
  th: {
    "philippines-philhealth-calculator": c("เครื่องคำนวณ PhilHealth ใช้เพดานล่างและบนกับเงินเดือนพื้นฐานรายเดือน แล้วแบ่งเบี้ยประกันระหว่างลูกจ้างและนายจ้างฝ่ายละครึ่ง อ้างอิงประกาศปี 2025 สำหรับ Direct Contributors และไม่ได้จำแนกสมาชิกประเภทอื่น", "กรอกเงินเดือนพื้นฐานรายเดือนเป็น PHP ระบบใช้ขั้นต่ำ PHP10,000 และสูงสุด PHP100,000 อย่ารวมค่าล่วงเวลา ค่านายหน้า หรือเงินช่วยเหลือไว้ในเงินเดือนพื้นฐาน", "ฐาน=min(100,000, max(10,000, เงินเดือนพื้นฐานรายเดือน)); เบี้ยรวม=ฐาน×5%; แต่ละฝ่าย=ยอดรวม÷2 ผลลัพธ์ปัดเศษสองตำแหน่ง", "เงินเดือนพื้นฐาน PHP30,000 ต่อเดือนให้เบี้ยรวม PHP1,500 ลูกจ้างและนายจ้างจ่ายฝ่ายละ PHP750 เป็นตัวอย่างตามประกาศปี 2025", "ค่าล่วงเวลาและเงินช่วยเหลือรวมในฐานหรือไม่?", "ประกาศปี 2025 ระบุว่าไม่รวมค่านายหน้า ค่าล่วงเวลา เงินช่วยเหลือ เงินเดือนเดือนที่ 13 โบนัส และรายการคล้ายกันใน Monthly Basic Salary โปรดตรวจประเภทสมาชิกและเงื่อนไขเฉพาะแยกต่างหาก"),
    "philippines-pagibig-calculator": c("เครื่องคำนวณ Pag-IBIG จำกัด Fund Salary รายเดือนไม่เกิน PHP10,000 และแสดงเงินออมของลูกจ้างกับนายจ้างแยกกัน คำอธิบายใช้เพดานที่มีผลตั้งแต่กุมภาพันธ์ 2024 และไม่วินิจฉัยข้อยกเว้นสมาชิก", "กรอกค่าตอบแทนรายเดือนเป็น PHP ตามอัตราทั่วไป อัตราของลูกจ้างขึ้นกับว่าฐานไม่เกิน PHP1,500 หรือสูงกว่า ส่วนของนายจ้างแสดงแยกต่างหาก", "Fund Salary=min(ค่าตอบแทนรายเดือน, PHP10,000); ลูกจ้าง=ฐาน×1% เมื่อ≤1,500 มิฉะนั้น 2%; นายจ้าง=ฐาน×2%; รวม=สองส่วนบวกกัน", "ค่าตอบแทน PHP30,000 ต่อเดือนถูกจำกัดฐานที่ PHP10,000 ระบบแสดงลูกจ้าง PHP200 นายจ้าง PHP200 รวม PHP400 เป็นตัวอย่างอัตราทั่วไป", "ส่วนของนายจ้างถูกหักจากเงินเดือนฉันหรือไม่?", "ไม่ใช่ เงินสมทบส่วนปกติของนายจ้างเป็นภาระของนายจ้าง ไม่ควรรวมเป็นรายการหักของลูกจ้าง ผู้ประกอบอาชีพอิสระหรือสมาชิกสมัครใจอาจมีวิธีชำระต่างกัน โปรดตรวจคำแนะนำของกองทุน"),
    "philippines-gross-net-salary-calculator": c("เครื่องมือนี้ประมาณภาษีรายปีและเงินสมทบบางส่วนของลูกจ้างจากเงินเดือนรวม พร้อมตัวเลือกปีหรือเดือน ไม่ใช่สลิปเงินเดือนหรือการคำนวณภาษีหัก ณ ที่จ่ายของ BIR", "กรอกเงินเดือนรวม PHP และเลือกรายปีหรือรายเดือน ระบบแปลงรายเดือนเป็นรายปีเพื่อประมาณภาษีแบบขั้นบันได แบบฟอร์มไม่รับองค์ประกอบที่เสีย/ยกเว้นภาษี ค่าลดหย่อน ผู้พึ่งพิง หรือข้อมูลเงินเดือนเดือนที่ 13", "เงินเดือนรวมรายปี=ค่ารายเดือน×12 หรือค่ารายปี ภาษีใช้ขั้นอัตรารายปีของระบบ เงินสมทบลูกจ้างคำนวณรายปีจาก SSS 5%(ฐานสูงสุด PHP35,000) และ PhilHealth 2.5%(สูงสุด PHP100,000); ไม่รวม Pag-IBIG", "เมื่อใส่ PHP60,000 ต่อเดือน ระบบให้เงินเดือนรวมรายปี PHP720,000 ภาษีประมาณ PHP86,500 เงินสมทบรายปี PHP39,000 สุทธิรายปี PHP594,500 และเฉลี่ยรายเดือน PHP49,541.67 เป็นผลจากระบบ ไม่ใช่ยอดหักเงินจริง", "เหตุใดผลลัพธ์จึงต่างจากสลิปเงินเดือน?", "แบบจำลองไม่ใช้ตารางหักภาษีตามรอบจ่าย ไม่แยกเงินได้ที่เสีย/ยกเว้นภาษี ค่าลดหย่อนหรือเครดิต และไม่รวม Pag-IBIG รวมทั้งช่วงเครดิตเงินเดือน SSS, EC และ MPF การป้อนเงินเดือนรายปียังมีข้อจำกัดเรื่องฐานสมทบรายเดือน จึงไม่รับประกันความแม่นยำด้าน payroll"),
  },
  it: {
    "philippines-philhealth-calculator": c("Il calcolatore PhilHealth applica un minimo e un massimo allo stipendio base mensile e divide il premio in parti uguali tra dipendente e datore. Il riferimento è l’avviso 2025 per i Direct Contributors; non stabilisce le altre categorie di iscrizione.", "Inserisci lo stipendio base mensile in PHP. Il motore applica un minimo di PHP10.000 e un massimo di PHP100.000. Non aggiungere straordinari, commissioni o indennità allo stipendio base.", "Base=min(100.000, max(10.000, stipendio base mensile)); premio totale=base×5%; ciascuna quota=totale÷2. I risultati sono arrotondati a due decimali.", "Con uno stipendio base mensile di PHP30.000, il premio totale è PHP1.500: PHP750 a carico del dipendente e PHP750 del datore. È un esempio aritmetico secondo l’avviso 2025.", "Straordinari e indennità entrano nella base?", "L’avviso 2025 esclude dallo Monthly Basic Salary commissioni, straordinari, indennità, tredicesima, bonus e voci simili. Verifica separatamente categoria di iscrizione e condizioni individuali."),
    "philippines-pagibig-calculator": c("Il calcolatore Pag-IBIG limita il Fund Salary mensile a PHP10.000 e mostra separatamente il risparmio del dipendente e la quota del datore. Il testo considera il limite in vigore da febbraio 2024 e non determina eccezioni di adesione.", "Inserisci la retribuzione mensile in PHP. Con le aliquote generali, la quota del dipendente dipende dal superamento di PHP1.500; la parte del datore è distinta.", "Fund Salary=min(retribuzione mensile, PHP10.000); dipendente=base×1% se ≤1.500, altrimenti 2%; datore=base×2%; totale=somma delle quote.", "Con PHP30.000 al mese, la base è limitata a PHP10.000: PHP200 dipendente, PHP200 datore, PHP400 totali. È un esempio con le aliquote generali.", "La quota del datore viene trattenuta dal mio stipendio?", "No. La quota ordinaria del datore è a suo carico e non va aggiunta alla trattenuta del dipendente. Autonomi e aderenti volontari possono avere obblighi diversi; consulta le istruzioni del Fondo."),
    "philippines-gross-net-salary-calculator": c("Questo strumento stima imposta annuale e alcune contribuzioni del dipendente in base alla retribuzione lorda e alla scelta annuale o mensile. Non sostituisce una busta paga né il calcolo della ritenuta BIR.", "Inserisci la retribuzione lorda in PHP e scegli annuale o mensile. Il valore mensile viene annualizzato per stimare l’imposta progressiva. Non vengono raccolti componenti imponibili/esenti, deduzioni, familiari a carico o dettagli della tredicesima.", "Lordo annuo=input mensile×12, altrimenti input annuo. L’imposta usa gli scaglioni annuali del motore. Le contribuzioni del dipendente annualizzano SSS 5%(base massima PHP35.000) e PhilHealth 2,5%(massimo PHP100.000); Pag-IBIG è escluso.", "Con PHP60.000 mensili, il motore restituisce lordo annuo PHP720.000, imposta stimata PHP86.500, contribuzioni annue PHP39.000, netto annuo PHP594.500 e equivalente mensile PHP49.541,67. È l’output del motore, non una trattenuta effettiva.", "Perché il risultato può differire dalla busta paga?", "Il modello non applica tabelle di ritenuta per periodo di paga, non classifica voci imponibili/esenti, deduzioni o crediti e omette Pag-IBIG e gli scaglioni di credito salariale SSS, EC e MPF. L’inserimento annuale ha inoltre un limite nella base mensile delle contribuzioni: la precisione payroll non è garantita."),
  },
  nl: {
    "philippines-philhealth-calculator": c("De PhilHealth-rekentool past een onder- en bovengrens toe op het maandelijkse basissalaris en verdeelt de premie gelijk over werknemer en werkgever. De verwijzing is de kennisgeving uit 2025 voor Direct Contributors; andere ledencategorieën worden niet vastgesteld.", "Vul het maandelijkse basissalaris in PHP in. De engine gebruikt minimaal PHP10.000 en maximaal PHP100.000. Tel overwerk, provisies of toeslagen niet bij het basissalaris op.", "Basis=min(100.000, max(10.000, maandelijks basissalaris)); totale premie=basis×5%; elk aandeel=totaal÷2. De weergave rondt af op twee decimalen.", "Bij PHP30.000 maandelijks basissalaris bedraagt de totale premie PHP1.500: PHP750 voor werknemer en PHP750 voor werkgever. Dit is een rekenvoorbeeld volgens de kennisgeving van 2025.", "Tellen overwerk en toeslagen mee in de basis?", "De kennisgeving uit 2025 sluit provisies, overwerk, toeslagen, 13e maand, bonussen en vergelijkbare betalingen uit van Monthly Basic Salary. Controleer lidmaatschapscategorie en persoonlijke voorwaarden apart."),
    "philippines-pagibig-calculator": c("De Pag-IBIG-rekentool begrenst het maandelijkse Fund Salary op PHP10.000 en toont de spaarbijdrage van werknemer en werkgever apart. De uitleg gebruikt de grens vanaf februari 2024 en bepaalt geen uitzonderingen voor leden.", "Vul de maandelijkse vergoeding in PHP in. Bij de algemene tarieven hangt het werknemerspercentage af van een basis tot en met PHP1.500 of daarboven; het werkgeversdeel staat apart.", "Fund Salary=min(maandvergoeding, PHP10.000); werknemer=basis×1% bij ≤1.500, anders 2%; werkgever=basis×2%; totaal=beide delen samen.", "Bij PHP30.000 per maand wordt de basis begrensd op PHP10.000: PHP200 werknemer, PHP200 werkgever, totaal PHP400. Dit illustreert de algemene tarieven.", "Wordt het werkgeversdeel van mijn loon afgetrokken?", "Nee. De gewone werkgeversbijdrage is voor rekening van de werkgever en hoort niet bij de inhouding van de werknemer. Zelfstandigen en vrijwillige leden kunnen anders bijdragen; raadpleeg de richtlijnen van het Fonds."),
    "philippines-gross-net-salary-calculator": c("Deze tool schat de jaarbelasting en enkele werknemersbijdragen op basis van brutoloon en een keuze voor jaar of maand. Het is geen loonstrook en geen BIR-berekening van loonheffing.", "Vul het brutoloon in PHP in en kies jaarlijks of maandelijks. Een maandbedrag wordt omgerekend naar jaarbasis voor de progressieve belastingschatting. Belastbare/vrijgestelde looncomponenten, aftrekposten, afhankelijken en 13e maand worden niet gevraagd.", "Bruto jaarloon=maandinvoer×12, anders de jaarinvoer. Belasting volgt de jaarlijkse schijven in de engine. Werknemersbijdragen worden geannualiseerd met SSS 5%(basis maximaal PHP35.000) en PhilHealth 2,5%(maximum PHP100.000); Pag-IBIG ontbreekt.", "Bij PHP60.000 per maand geeft de engine PHP720.000 bruto per jaar, PHP86.500 geschatte belasting, PHP39.000 jaarbijdragen, PHP594.500 netto per jaar en PHP49.541,67 per maand. Dit is een engine-uitkomst, geen werkelijke looninhouding.", "Waarom kan dit afwijken van mijn loonstrook?", "Het model gebruikt geen inhoudingstabellen per loonperiode, classificeert geen belastbare/vrijgestelde delen, aftrekposten of kredieten en laat Pag-IBIG en SSS-kredietklassen, EC en MPF weg. Ook is de maandelijkse bijdragebasis beperkt bij jaarinvoer; loonadministratieve nauwkeurigheid is niet gegarandeerd."),
  },
  hi: {
    "philippines-philhealth-calculator": c("यह PhilHealth उपकरण मासिक मूल वेतन पर न्यूनतम और अधिकतम सीमा लगाकर प्रीमियम निकालता है और कर्मचारी तथा नियोक्ता के बीच बराबर बाँटता है। संदर्भ 2025 का Direct Contributors नोटिस है; यह अन्य सदस्य श्रेणियों का निर्धारण नहीं करता।", "PHP में मासिक मूल वेतन दर्ज करें। इंजन PHP10,000 से कम को न्यूनतम और PHP100,000 से अधिक को अधिकतम मानता है। ओवरटाइम, कमीशन या भत्ते को मूल वेतन में न जोड़ें।", "आधार=min(100,000, max(10,000, मासिक मूल वेतन)); कुल प्रीमियम=आधार×5%; प्रत्येक हिस्सा=कुल÷2। परिणाम दो दशमलव तक राउंड होते हैं।", "PHP30,000 मासिक मूल वेतन पर कुल प्रीमियम PHP1,500 है; कर्मचारी और नियोक्ता प्रत्येक PHP750 देते हैं। यह 2025 नोटिस के अनुसार अंकगणितीय उदाहरण है।", "क्या ओवरटाइम और भत्ते आधार में शामिल हैं?", "2025 नोटिस Monthly Basic Salary से कमीशन, ओवरटाइम, भत्ते, 13वें महीने का वेतन, बोनस और समान भुगतान बाहर रखता है। सदस्य श्रेणी और व्यक्तिगत पात्रता अलग से जाँचें।"),
    "philippines-pagibig-calculator": c("Pag-IBIG कैलकुलेटर मासिक Fund Salary को PHP10,000 तक सीमित करता है और कर्मचारी व नियोक्ता की बचत अलग दिखाता है। विवरण फरवरी 2024 से लागू सीमा पर आधारित है; सदस्य अपवादों का निर्णय नहीं करता।", "PHP में मासिक पारिश्रमिक दर्ज करें। सामान्य दर में कर्मचारी का हिस्सा इस पर निर्भर करता है कि आधार PHP1,500 तक है या उससे अधिक; नियोक्ता का हिस्सा अलग दिखता है।", "Fund Salary=min(मासिक पारिश्रमिक, PHP10,000); कर्मचारी=आधार×1% यदि ≤1,500, अन्यथा 2%; नियोक्ता=आधार×2%; कुल=दोनों हिस्सों का योग।", "PHP30,000 मासिक पारिश्रमिक पर आधार PHP10,000 तक सीमित है: कर्मचारी PHP200, नियोक्ता PHP200, कुल PHP400। यह सामान्य दर का उदाहरण है।", "क्या नियोक्ता का हिस्सा मेरे वेतन से कटता है?", "नहीं। सामान्य नियोक्ता counterpart नियोक्ता की जिम्मेदारी है और इसे कर्मचारी कटौती में नहीं जोड़ना चाहिए। स्व-रोज़गार और स्वैच्छिक सदस्यों की जिम्मेदारी अलग हो सकती है; Fund guidance देखें।"),
    "philippines-gross-net-salary-calculator": c("यह उपकरण सकल वेतन और वार्षिक/मासिक विकल्प से वार्षिक कर तथा कुछ कर्मचारी योगदान का अनुमान लगाता है। यह वेतन पर्ची या BIR withholding calculation नहीं है।", "PHP सकल वेतन दर्ज करें और वार्षिक या मासिक चुनें। प्रगतिशील कर अनुमान के लिए मासिक राशि को सालाना किया जाता है। करयोग्य/छूट प्राप्त मदें, कटौतियाँ, आश्रित और 13वें महीने के वेतन का विवरण नहीं लिया जाता।", "वार्षिक सकल=मासिक इनपुट×12, अन्यथा वार्षिक इनपुट। कर इंजन के वार्षिक स्लैब से है। कर्मचारी योगदान SSS 5%(आधार अधिकतम PHP35,000) और PhilHealth 2.5%(अधिकतम PHP100,000) से वार्षिक किए जाते हैं; Pag-IBIG शामिल नहीं है।", "PHP60,000 मासिक पर इंजन वार्षिक सकल PHP720,000, अनुमानित कर PHP86,500, वार्षिक कर्मचारी योगदान PHP39,000, वार्षिक शुद्ध PHP594,500 और मासिक समतुल्य PHP49,541.67 देता है। यह इंजन परिणाम है, वास्तविक payroll कटौती नहीं।", "परिणाम वेतन पर्ची से अलग क्यों हो सकता है?", "मॉडल भुगतान-अवधि वाली withholding tables, करयोग्य/छूट आय, कटौती या tax credits को लागू नहीं करता; Pag-IBIG और SSS salary-credit bands, EC और MPF भी नहीं हैं। वार्षिक इनपुट पर योगदान का मासिक आधार भी सीमित है, इसलिए payroll सटीकता की गारंटी नहीं है।"),
  },
  ru: {
    "philippines-philhealth-calculator": c("Калькулятор PhilHealth применяет минимум и максимум к месячному базовому окладу, затем делит премию поровну между работником и работодателем. Справка относится к уведомлению 2025 года для Direct Contributors и не определяет другие категории участников.", "Введите месячный базовый оклад в PHP. Движок использует минимум PHP10 000 и максимум PHP100 000. Не включайте сверхурочные, комиссионные и надбавки в базовый оклад.", "База=min(100 000, max(10 000, месячный базовый оклад)); премия=база×5%; доля каждой стороны=премия÷2. Отображение округляется до двух знаков.", "При окладе PHP30 000 в месяц общая премия равна PHP1 500, по PHP750 для работника и работодателя. Это арифметический пример по уведомлению 2025 года.", "Входят ли сверхурочные и надбавки в базу?", "Уведомление 2025 года исключает из Monthly Basic Salary комиссии, сверхурочные, надбавки, 13-ю зарплату, бонусы и подобные выплаты. Категорию участника и личные условия нужно проверять отдельно."),
    "philippines-pagibig-calculator": c("Калькулятор Pag-IBIG ограничивает месячную базу Fund Salary суммой PHP10 000 и отдельно показывает сбережения работника и работодателя. Текст учитывает предел с февраля 2024 года, но не определяет исключения по членству.", "Введите месячное вознаграждение в PHP. При общих ставках доля работника зависит от того, превышает ли база PHP1 500; доля работодателя показывается отдельно.", "Fund Salary=min(месячное вознаграждение, PHP10 000); работник=база×1% при ≤1 500, иначе 2%; работодатель=база×2%; итог — сумма долей.", "При PHP30 000 в месяц база ограничивается PHP10 000: PHP200 работник, PHP200 работодатель, всего PHP400. Это пример общих ставок.", "Удерживается ли доля работодателя из моей зарплаты?", "Нет. Обычная доля работодателя оплачивается работодателем и не должна прибавляться к удержанию работника. Для самозанятых и добровольных участников могут действовать иные обязанности; проверьте указания Фонда."),
    "philippines-gross-net-salary-calculator": c("Инструмент оценивает годовой налог и часть взносов работника по брутто-зарплате и выбору годового или месячного периода. Он не заменяет расчетный листок или расчет удержания BIR.", "Введите брутто-зарплату в PHP и выберите годовой или месячный период. Месячная сумма переводится в годовую для оценки прогрессивного налога. Налогооблагаемые/освобожденные выплаты, вычеты, иждивенцы и 13-я зарплата не запрашиваются.", "Годовой брутто=месячный ввод×12 либо годовой ввод. Налог рассчитывается по годовым диапазонам движка. Взносы работника годируются по SSS 5%(база до PHP35 000) и PhilHealth 2,5%(до PHP100 000); Pag-IBIG не включен.", "При PHP60 000 в месяц движок выдает годовой брутто PHP720 000, налог PHP86 500, годовые взносы PHP39 000, годовой нетто PHP594 500 и месячный эквивалент PHP49 541,67. Это результат движка, а не фактическое удержание.", "Почему сумма может отличаться от расчетного листка?", "Модель не использует таблицы удержаний для периода выплат, не классифицирует облагаемые/освобожденные выплаты, вычеты или налоговые зачеты, а также пропускает Pag-IBIG и диапазоны SSS, EC и MPF. При годовом вводе действует ограничение месячной базы взносов; точность payroll не гарантируется."),
  },
  tr: {
    "philippines-philhealth-calculator": c("PhilHealth aracı aylık temel maaşa alt ve üst sınır uygular, ardından primi çalışan ile işveren arasında eşit böler. Referans, Direct Contributors için 2025 duyurusudur; diğer üyelik kategorilerini belirlemez.", "Aylık temel maaşı PHP olarak girin. Motor en az PHP10.000, en çok PHP100.000 taban kullanır. Fazla mesai, komisyon veya ödenekleri temel maaşa eklemeyin.", "Taban=min(100.000, max(10.000, aylık temel maaş)); toplam prim=taban×5%; taraf başına=toplam÷2. Sonuç iki ondalık basamağa yuvarlanır.", "Aylık PHP30.000 temel maaşta toplam prim PHP1.500; çalışan ve işveren payları ayrı ayrı PHP750 olur. Bu, 2025 duyurusuna göre aritmetik bir örnektir.", "Fazla mesai ve ödenekler tabana girer mi?", "2025 duyurusu komisyon, fazla mesai, ödenek, 13. ay ücreti, ikramiye ve benzerlerini Monthly Basic Salary dışında tutar. Üyelik kategorisini ve kişisel koşulları ayrıca doğrulayın."),
    "philippines-pagibig-calculator": c("Pag-IBIG aracı aylık Fund Salary tutarını PHP10.000 ile sınırlar ve çalışan ile işveren tasarruf paylarını ayrı gösterir. Açıklama Şubat 2024'ten beri geçerli tavanı kullanır; üyelik istisnalarını belirlemez.", "Aylık ücreti PHP olarak girin. Genel oranlarda çalışan payı, tabanın PHP1.500'ü aşıp aşmamasına bağlıdır; işveren payı ayrı gösterilir.", "Fund Salary=min(aylık ücret, PHP10.000); çalışan=taban×(≤1.500 ise %1, üzerindeyse %2); işveren=taban×%2; toplam=iki payın toplamı.", "Aylık PHP30.000 ücrette taban PHP10.000 ile sınırlanır: çalışan PHP200, işveren PHP200, toplam PHP400. Bu genel oran örneğidir.", "İşveren payı maaşımdan kesilir mi?", "Hayır. Olağan işveren karşılığı işverenin yükümlülüğüdür ve çalışan kesintisine eklenmemelidir. Serbest çalışanlar ve gönüllü üyeler farklı ödeme sorumluluklarına sahip olabilir; Fonun rehberini kontrol edin."),
    "philippines-gross-net-salary-calculator": c("Bu araç brüt ücret ve yıllık/aylık dönem seçimine göre yıllık vergi ile bazı çalışan katkılarını tahmin eder. Bordro belgesinin veya BIR stopaj hesabının yerine geçmez.", "PHP brüt ücreti girip yıllık veya aylık seçin. Aylık giriş, artan oranlı vergi tahmini için yıllıklandırılır. Vergili/istisna kalemleri, indirimler, bakmakla yükümlü olunanlar ve 13. ay ücreti alınmaz.", "Yıllık brüt=aylık giriş×12 veya yıllık giriş. Vergi motorun yıllık dilimlerine göre hesaplanır. Çalışan katkıları SSS %5(PHP35.000 taban tavanı) ve PhilHealth %2,5(PHP100.000 tavanı) ile yıllıklaştırılır; Pag-IBIG dahil değildir.", "Aylık PHP60.000 için motor yıllık brüt PHP720.000, tahmini vergi PHP86.500, yıllık katkı PHP39.000, yıllık net PHP594.500 ve aylık karşılık PHP49.541,67 verir. Bu motor çıktısıdır, gerçek bordro kesintisi değildir.", "Sonuç neden maaş bordromdan farklı olabilir?", "Model ödeme dönemine göre stopaj tabloları kullanmaz; vergiye tabi/istisna ücretleri, indirim ve kredileri sınıflandırmaz; Pag-IBIG ile SSS ücret kredisi dilimleri, EC ve MPF'yi de dışarıda bırakır. Yıllık giriş katkı tabanı aylık işlenirken sınırlıdır; bordro doğruluğu garanti edilmez."),
  },
  pl: {
    "philippines-philhealth-calculator": c("Kalkulator PhilHealth stosuje dolny i górny limit do miesięcznego wynagrodzenia podstawowego, a następnie dzieli składkę po równo między pracownika i pracodawcę. Odniesieniem jest komunikat z 2025 r. dla Direct Contributors; narzędzie nie ustala innych kategorii członkostwa.", "Wpisz miesięczne wynagrodzenie podstawowe w PHP. Silnik stosuje minimum PHP10 000 i maksimum PHP100 000. Nie dodawaj nadgodzin, prowizji ani dodatków do podstawy.", "Podstawa=min(100 000, max(10 000, miesięczne wynagrodzenie podstawowe)); składka łączna=podstawa×5%; każda część=łączna÷2. Wynik jest zaokrąglany do dwóch miejsc.", "Przy miesięcznej podstawie PHP30 000 składka wynosi łącznie PHP1 500, po PHP750 dla pracownika i pracodawcy. To przykład arytmetyczny według komunikatu z 2025 r.", "Czy nadgodziny i dodatki wchodzą do podstawy?", "Komunikat z 2025 r. wyłącza z Monthly Basic Salary prowizje, nadgodziny, dodatki, wynagrodzenie za 13. miesiąc, premie i podobne pozycje. Kategorię członkostwa i warunki indywidualne sprawdź osobno."),
    "philippines-pagibig-calculator": c("Kalkulator Pag-IBIG ogranicza miesięczny Fund Salary do PHP10 000 i osobno pokazuje oszczędności pracownika oraz pracodawcy. Opis uwzględnia limit obowiązujący od lutego 2024 r., ale nie ustala wyjątków członkowskich.", "Wpisz miesięczne wynagrodzenie w PHP. Przy stawkach ogólnych część pracownika zależy od tego, czy podstawa przekracza PHP1 500; udział pracodawcy jest pokazany oddzielnie.", "Fund Salary=min(wynagrodzenie miesięczne, PHP10 000); pracownik=podstawa×1% przy ≤1 500, w przeciwnym razie 2%; pracodawca=podstawa×2%; suma=obie części.", "Przy PHP30 000 miesięcznie podstawa jest ograniczona do PHP10 000: PHP200 pracownik, PHP200 pracodawca, łącznie PHP400. To przykład stawek ogólnych.", "Czy udział pracodawcy potrąca się z mojej pensji?", "Nie. Zwykły udział pracodawcy jest jego kosztem i nie należy dodawać go do potrącenia pracownika. Osoby samozatrudnione i członkowie dobrowolni mogą mieć inne obowiązki; sprawdź wytyczne Funduszu."),
    "philippines-gross-net-salary-calculator": c("To narzędzie szacuje roczny podatek i wybrane składki pracownika na podstawie wynagrodzenia brutto i wyboru roku lub miesiąca. Nie zastępuje listy płac ani obliczenia potrącenia BIR.", "Wpisz wynagrodzenie brutto w PHP i wybierz rok lub miesiąc. Kwota miesięczna jest annualizowana do szacunku podatku progresywnego. Formularz nie pyta o składniki opodatkowane/zwolnione, odliczenia, osoby na utrzymaniu ani 13. pensję.", "Brutto roczne=wejście miesięczne×12 albo wejście roczne. Podatek korzysta z rocznych progów silnika. Składki pracownika annualizują SSS 5%(podstawa do PHP35 000) i PhilHealth 2,5%(limit PHP100 000); Pag-IBIG pominięto.", "Przy PHP60 000 miesięcznie silnik zwraca PHP720 000 brutto rocznie, PHP86 500 szacowanego podatku, PHP39 000 składek rocznych, PHP594 500 netto rocznie i PHP49 541,67 miesięcznie. To wynik silnika, a nie rzeczywiste potrącenie z listy płac.", "Dlaczego wynik może różnić się od paska płacowego?", "Model nie stosuje tabel potrąceń według okresu wypłaty, nie klasyfikuje składników opodatkowanych/zwolnionych, ulg ani odliczeń, pomija Pag-IBIG oraz progi kredytu płacowego SSS, EC i MPF. Przy wejściu rocznym podstawa składek ma ograniczenie miesięczne, więc dokładność listy płac nie jest gwarantowana."),
  },
  fil: {
    "philippines-philhealth-calculator": c("Inaangkop ng PhilHealth calculator ang minimum at maximum sa buwanang basic salary, saka hinahati nang pantay ang premium sa empleyado at employer. Ang sanggunian ay ang 2025 advisory para sa Direct Contributors; hindi nito tinutukoy ang ibang membership category.", "Ilagay ang buwanang basic salary sa PHP. Gumagamit ang engine ng minimum na PHP10,000 at maximum na PHP100,000. Huwag isama ang overtime, komisyon, o allowance sa basic salary.", "Base=min(100,000, max(10,000, buwanang basic salary)); kabuuang premium=base×5%; bawat bahagi=kabuuan÷2. Ni-round sa dalawang decimal place ang ipinapakita.", "Kung PHP30,000 ang buwanang basic salary, PHP1,500 ang kabuuang premium: PHP750 para sa empleyado at PHP750 para sa employer. Halimbawang arithmetic ito ayon sa 2025 advisory.", "Kasama ba sa base ang overtime at allowance?", "Hindi kasama sa Monthly Basic Salary sa 2025 advisory ang komisyon, overtime, allowance, 13th-month pay, bonus, at kahalintulad na bayad. Suriin nang hiwalay ang membership category at personal na kondisyon."),
    "philippines-pagibig-calculator": c("Nililimitahan ng Pag-IBIG calculator sa PHP10,000 ang buwanang Fund Salary at magkahiwalay na ipinapakita ang ipon ng empleyado at employer. Ginagamit ng paliwanag ang limitasyong epektibo mula Pebrero 2024 at hindi nito tinutukoy ang mga exception sa membership.", "Ilagay ang buwanang compensation sa PHP. Sa pangkalahatang rate, nakadepende ang bahagi ng empleyado kung lampas sa PHP1,500 ang base; hiwalay ang ipinapakitang bahagi ng employer.", "Fund Salary=min(buwanang compensation, PHP10,000); empleyado=base×1% kung ≤1,500, kung hindi 2%; employer=base×2%; kabuuan=pinagsamang bahagi.", "Sa PHP30,000 buwanang compensation, nililimitahan ang base sa PHP10,000: PHP200 empleyado, PHP200 employer, PHP400 lahat. Halimbawa ito ng pangkalahatang rate.", "Ibinabawas ba sa sahod ko ang bahagi ng employer?", "Hindi. Ang karaniwang employer counterpart ay pananagutan ng employer at hindi dapat idagdag sa kaltas ng empleyado. Maaaring iba ang obligasyon ng self-employed at boluntaryong miyembro; tingnan ang gabay ng Fund."),
    "philippines-gross-net-salary-calculator": c("Tinatantiya ng tool na ito ang taunang buwis at ilang kontribusyon ng empleyado mula sa gross salary at pagpiling taon o buwan. Hindi ito payslip o kalkulasyon ng withholding tax ng BIR.", "Ilagay ang gross salary sa PHP at piliin ang taun-taon o buwanan. Ginagawang taun-taon ang buwanang halaga para sa tantiya ng progressive tax. Hindi kinukuha ang taxable/exempt pay items, deductions, dependents, o detalye ng 13th-month pay.", "Taunang gross=monthly input×12 o annual input. Ginagamit ang annual brackets ng engine. Ginagawang taunang halaga ang SSS 5%(base hanggang PHP35,000) at PhilHealth 2.5%(hanggang PHP100,000); hindi kasama ang Pag-IBIG.", "Sa PHP60,000 buwanan, ibinabalik ng engine ang PHP720,000 annual gross, PHP86,500 tantiya sa buwis, PHP39,000 taunang kontribusyon, PHP594,500 taunang net, at PHP49,541.67 katumbas kada buwan. Engine output ito, hindi aktuwal na kaltas sa payroll.", "Bakit maaaring iba ito sa payslip?", "Hindi gumagamit ang modelo ng withholding table ayon sa pay period, hindi pinag-iiba ang taxable/exempt pay, deductions o credits, at hindi kasama ang Pag-IBIG o salary-credit bands, EC at MPF ng SSS. May limitasyon din sa monthly contribution base kapag annual ang input kaya hindi garantisado ang payroll accuracy."),
  },
  bn: {
    "philippines-philhealth-calculator": c("PhilHealth ক্যালকুলেটর মাসিক মূল বেতনে সর্বনিম্ন ও সর্বোচ্চ সীমা প্রয়োগ করে, তারপর প্রিমিয়াম কর্মী ও নিয়োগকর্তার মধ্যে সমান ভাগ করে। উল্লেখিত ভিত্তি ২০২৫ সালের Direct Contributors বিজ্ঞপ্তি; অন্য সদস্য শ্রেণি নির্ধারণ করা হয় না।", "PHP-তে মাসিক মূল বেতন লিখুন। ইঞ্জিন PHP10,000-এর নিচে ন্যূনতম এবং PHP100,000-এর ওপরে সর্বোচ্চ ভিত্তি নেয়। ওভারটাইম, কমিশন বা ভাতা মূল বেতনে যোগ করবেন না।", "ভিত্তি=min(100,000, max(10,000, মাসিক মূল বেতন)); মোট প্রিমিয়াম=ভিত্তি×5%; প্রত্যেকের অংশ=মোট÷2। প্রদর্শিত মান দুই দশমিক স্থানে রাউন্ড হয়।", "মাসিক মূল বেতন PHP30,000 হলে মোট প্রিমিয়াম PHP1,500; কর্মী ও নিয়োগকর্তা প্রত্যেকে PHP750 দেন। এটি ২০২৫ বিজ্ঞপ্তির ভিত্তিতে গাণিতিক উদাহরণ।", "ওভারটাইম ও ভাতা কি ভিত্তিতে থাকে?", "২০২৫ বিজ্ঞপ্তিতে কমিশন, ওভারটাইম, ভাতা, ১৩তম মাসের বেতন, বোনাস ও অনুরূপ অর্থ Monthly Basic Salary থেকে বাদ। সদস্য শ্রেণি ও ব্যক্তিগত শর্ত আলাদাভাবে যাচাই করুন।"),
    "philippines-pagibig-calculator": c("Pag-IBIG ক্যালকুলেটর মাসিক Fund Salary PHP10,000-এ সীমাবদ্ধ করে এবং কর্মী ও নিয়োগকর্তার সঞ্চয় আলাদা দেখায়। ব্যাখ্যাটি ফেব্রুয়ারি ২০২৪ থেকে কার্যকর সীমা ব্যবহার করে; সদস্যতার ব্যতিক্রম নির্ধারণ করে না।", "PHP-তে মাসিক পারিশ্রমিক লিখুন। সাধারণ হারে ভিত্তি PHP1,500-এর বেশি কি না তার ওপর কর্মীর হার নির্ভর করে; নিয়োগকর্তার অংশ আলাদা দেখানো হয়।", "Fund Salary=min(মাসিক পারিশ্রমিক, PHP10,000); কর্মী=ভিত্তি×1% যদি ≤1,500, নইলে 2%; নিয়োগকর্তা=ভিত্তি×2%; মোট=দুই অংশের যোগফল।", "মাসিক PHP30,000 হলে ভিত্তি PHP10,000-এ সীমিত হয়: কর্মী PHP200, নিয়োগকর্তা PHP200, মোট PHP400। এটি সাধারণ হারের উদাহরণ।", "নিয়োগকর্তার অংশ কি আমার বেতন থেকে কাটা হয়?", "না। সাধারণ নিয়োগকর্তা counterpart নিয়োগকর্তার দায়; কর্মীর কর্তনে যোগ করা উচিত নয়। স্বনিয়োজিত ও স্বেচ্ছাসেবী সদস্যের দায় ভিন্ন হতে পারে; Fund-এর নির্দেশনা দেখুন।"),
    "philippines-gross-net-salary-calculator": c("এই টুল মোট বেতন ও বার্ষিক/মাসিক নির্বাচন থেকে বার্ষিক কর এবং কর্মীর কিছু অবদান অনুমান করে। এটি বেতন স্লিপ বা BIR withholding tax হিসাব নয়।", "PHP-তে মোট বেতন লিখে বার্ষিক বা মাসিক নির্বাচন করুন। প্রগতিশীল কর অনুমানের জন্য মাসিক ইনপুটকে বার্ষিক করা হয়। করযোগ্য/অব্যাহতি আয়, ছাড়, নির্ভরশীল ব্যক্তি বা ১৩তম মাসের তথ্য নেওয়া হয় না।", "বার্ষিক মোট বেতন=মাসিক ইনপুট×12, অন্যথায় বার্ষিক ইনপুট। কর ইঞ্জিনের বার্ষিক ধাপ ব্যবহার করে। কর্মীর অবদান SSS 5%(ভিত্তি সর্বোচ্চ PHP35,000) ও PhilHealth 2.5%(সর্বোচ্চ PHP100,000) থেকে বার্ষিক করা হয়; Pag-IBIG নেই।", "মাসে PHP60,000 দিলে ইঞ্জিন বার্ষিক মোট PHP720,000, আনুমানিক কর PHP86,500, বার্ষিক অবদান PHP39,000, বার্ষিক নিট PHP594,500 এবং মাসিক সমতুল্য PHP49,541.67 দেয়। এটি ইঞ্জিনের ফল, প্রকৃত payroll কর্তন নয়।", "বেতন স্লিপের সঙ্গে ফল আলাদা হতে পারে কেন?", "মডেল বেতন-পর্বভিত্তিক withholding table, করযোগ্য/অব্যাহতি আয়, ছাড় বা tax credit প্রয়োগ করে না; Pag-IBIG এবং SSS salary-credit band, EC, MPF-ও বাদ। বার্ষিক ইনপুটে মাসিক অবদান ভিত্তির সীমা রয়েছে, তাই payroll নির্ভুলতা নিশ্চিত নয়।"),
  },
  uk: {
    "philippines-philhealth-calculator": c("Калькулятор PhilHealth застосовує мінімум і максимум до місячного базового окладу, а потім ділить премію порівну між працівником і роботодавцем. Орієнтир — повідомлення 2025 року для Direct Contributors; інші категорії учасників не визначаються.", "Введіть місячний базовий оклад у PHP. Рушій бере щонайменше PHP10 000 і не більше PHP100 000. Не додавайте понаднормові, комісійні чи надбавки до базового окладу.", "База=min(100 000, max(10 000, місячний базовий оклад)); загальна премія=база×5%; частка кожної сторони=сума÷2. Відображення округлюється до двох знаків.", "За базового окладу PHP30 000 на місяць загальна премія становить PHP1 500: по PHP750 для працівника й роботодавця. Це арифметичний приклад за повідомленням 2025 року.", "Чи входять понаднормові та надбавки до бази?", "Повідомлення 2025 року виключає комісійні, понаднормові, надбавки, 13-ту зарплату, бонуси та подібні виплати з Monthly Basic Salary. Категорію учасника й особисті умови перевіряйте окремо."),
    "philippines-pagibig-calculator": c("Калькулятор Pag-IBIG обмежує місячну базу Fund Salary сумою PHP10 000 і окремо показує заощадження працівника та роботодавця. Пояснення враховує межу з лютого 2024 року, але не визначає винятки членства.", "Введіть місячну винагороду в PHP. За загальними ставками частка працівника залежить від того, чи перевищує база PHP1 500; внесок роботодавця показано окремо.", "Fund Salary=min(місячна винагорода, PHP10 000); працівник=база×1% при ≤1 500, інакше 2%; роботодавець=база×2%; разом=сума часток.", "За винагороди PHP30 000 на місяць база обмежується PHP10 000: PHP200 працівник, PHP200 роботодавець, разом PHP400. Це приклад загальних ставок.", "Чи утримують частку роботодавця з моєї зарплати?", "Ні. Звичайний внесок роботодавця є його зобов’язанням і не додається до утримання працівника. Для самозайнятих і добровільних учасників можуть діяти інші умови; перевірте роз’яснення Фонду."),
    "philippines-gross-net-salary-calculator": c("Інструмент оцінює річний податок і частину внесків працівника за валовою зарплатою та вибором річного або місячного періоду. Це не розрахунковий лист і не розрахунок утримання BIR.", "Введіть валову зарплату в PHP і виберіть рік або місяць. Місячну суму річно перераховують для оцінки прогресивного податку. Форма не збирає оподатковувані/звільнені виплати, вирахування, утриманців чи дані про 13-ту зарплату.", "Річна валова=місячний ввід×12 або річний ввід. Податок використовує річні діапазони рушія. Внески працівника річно обчислюються за SSS 5%(база до PHP35 000) і PhilHealth 2,5%(до PHP100 000); Pag-IBIG не враховано.", "За PHP60 000 на місяць рушій повертає річну валову PHP720 000, податок PHP86 500, річні внески PHP39 000, річну чисту суму PHP594 500 і місячний еквівалент PHP49 541,67. Це результат рушія, не фактичне утримання із зарплати.", "Чому результат може відрізнятися від розрахункового листа?", "Модель не використовує таблиці утримання за періодами виплат, не класифікує оподатковувані/звільнені суми, вирахування чи кредити, а також пропускає Pag-IBIG і діапазони SSS, EC та MPF. Для річного вводу база внесків має місячне обмеження, тому точність payroll не гарантується."),
  },
  ms: {
    "philippines-philhealth-calculator": c("Kalkulator PhilHealth mengenakan had minimum dan maksimum pada gaji asas bulanan, kemudian membahagikan premium sama rata antara pekerja dan majikan. Rujukan ialah notis 2025 untuk Direct Contributors; kategori ahli lain tidak ditentukan.", "Masukkan gaji asas bulanan dalam PHP. Enjin menggunakan minimum PHP10,000 dan maksimum PHP100,000. Jangan masukkan kerja lebih masa, komisen atau elaun ke dalam gaji asas.", "Asas=min(100,000, max(10,000, gaji asas bulanan)); jumlah premium=asas×5%; setiap bahagian=jumlah÷2. Paparan dibundarkan kepada dua tempat perpuluhan.", "Dengan gaji asas PHP30,000 sebulan, premium berjumlah PHP1,500: PHP750 setiap seorang untuk pekerja dan majikan. Ini contoh aritmetik berdasarkan notis 2025.", "Adakah kerja lebih masa dan elaun termasuk dalam asas?", "Notis 2025 mengecualikan komisen, kerja lebih masa, elaun, gaji bulan ke-13, bonus dan bayaran seumpamanya daripada Monthly Basic Salary. Semak kategori ahli dan syarat individu secara berasingan."),
    "philippines-pagibig-calculator": c("Kalkulator Pag-IBIG mengehadkan Fund Salary bulanan kepada PHP10,000 dan memaparkan simpanan pekerja serta majikan secara berasingan. Penerangan menggunakan had berkuat kuasa sejak Februari 2024 dan tidak menentukan pengecualian keahlian.", "Masukkan pampasan bulanan dalam PHP. Bagi kadar umum, bahagian pekerja bergantung pada sama ada asas melebihi PHP1,500; bahagian majikan dipaparkan berasingan.", "Fund Salary=min(pampasan bulanan, PHP10,000); pekerja=asas×1% jika ≤1,500, selainnya 2%; majikan=asas×2%; jumlah=campuran kedua-dua bahagian.", "Dengan pampasan PHP30,000 sebulan, asas dihadkan kepada PHP10,000: PHP200 pekerja, PHP200 majikan, jumlah PHP400. Ini contoh kadar umum.", "Adakah bahagian majikan dipotong daripada gaji saya?", "Tidak. Bahagian majikan biasa ialah tanggungjawab majikan dan tidak patut ditambah kepada potongan pekerja. Bekerja sendiri dan ahli sukarela mungkin mempunyai tanggungjawab berlainan; rujuk panduan Dana."),
    "philippines-gross-net-salary-calculator": c("Alat ini menganggarkan cukai tahunan dan beberapa caruman pekerja daripada gaji kasar serta pilihan tahunan atau bulanan. Ia bukan penyata gaji atau pengiraan cukai pegangan BIR.", "Masukkan gaji kasar PHP dan pilih tahunan atau bulanan. Input bulanan dianualkan untuk anggaran cukai progresif. Borang tidak meminta komponen bercukai/dikecualikan, potongan, tanggungan atau butiran gaji bulan ke-13.", "Gaji kasar tahunan=input bulanan×12 atau input tahunan. Cukai menggunakan jalur tahunan enjin. Caruman pekerja dianualkan berdasarkan SSS 5%(asas maksimum PHP35,000) dan PhilHealth 2.5%(maksimum PHP100,000); Pag-IBIG tidak disertakan.", "Bagi PHP60,000 sebulan, enjin memulangkan gaji kasar tahunan PHP720,000, cukai anggaran PHP86,500, caruman tahunan PHP39,000, bersih tahunan PHP594,500 dan setara bulanan PHP49,541.67. Ini output enjin, bukan potongan gaji sebenar.", "Mengapa hasil boleh berbeza daripada slip gaji?", "Model tidak menggunakan jadual pegangan mengikut tempoh gaji, tidak mengelaskan komponen bercukai/dikecualikan, potongan atau kredit, dan mengabaikan Pag-IBIG serta jalur kredit gaji SSS, EC dan MPF. Input tahunan juga mempunyai batas asas caruman bulanan, maka ketepatan payroll tidak dijamin."),
  },
  sv: {
    "philippines-philhealth-calculator": c("PhilHealth-verktyget tillämpar ett golv och ett tak på månadslönen och delar sedan premien lika mellan arbetstagare och arbetsgivare. Hänvisningen är 2025 års besked för Direct Contributors; andra medlemskategorier avgörs inte.", "Ange månadslön i PHP. Motorn använder minst PHP10 000 och högst PHP100 000. Lägg inte till övertid, provision eller tillägg i grundlönen.", "Underlag=min(100 000, max(10 000, månadslön)); total premie=underlag×5%; vardera andelen=total÷2. Visningen avrundas till två decimaler.", "Vid PHP30 000 i månadslön blir total premie PHP1 500, alltså PHP750 vardera för arbetstagare och arbetsgivare. Detta är ett räkneexempel enligt 2025 års besked.", "Ingår övertid och tillägg i underlaget?", "Beskedet från 2025 utesluter provision, övertid, tillägg, 13:e månadslön, bonusar och liknande från Monthly Basic Salary. Kontrollera medlemskategori och individuella villkor separat."),
    "philippines-pagibig-calculator": c("Pag-IBIG-verktyget begränsar månatlig Fund Salary till PHP10 000 och visar arbetstagarens och arbetsgivarens sparande separat. Texten använder gränsen från februari 2024 men avgör inte medlemsundantag.", "Ange månatlig ersättning i PHP. Enligt de allmänna satserna beror arbetstagarens andel på om underlaget är högst PHP1 500; arbetsgivarens andel visas separat.", "Fund Salary=min(månatlig ersättning, PHP10 000); arbetstagare=underlag×1% vid ≤1 500, annars 2%; arbetsgivare=underlag×2%; totalt=summan.", "Vid PHP30 000 i månadsersättning begränsas underlaget till PHP10 000: PHP200 arbetstagare, PHP200 arbetsgivare, PHP400 totalt. Detta är ett exempel med allmänna satser.", "Dras arbetsgivarens andel från min lön?", "Nej. Den vanliga arbetsgivarandelen är arbetsgivarens ansvar och ska inte läggas till arbetstagarens avdrag. Egenföretagare och frivilliga medlemmar kan ha andra skyldigheter; se fondens vägledning."),
    "philippines-gross-net-salary-calculator": c("Verktyget uppskattar årsskatt och vissa arbetstagaravgifter utifrån bruttolön och valet år eller månad. Det ersätter varken lönespecifikation eller BIR:s skatteavdrag.", "Ange bruttolön i PHP och välj år eller månad. Månadslön räknas om till år för den progressiva skatteuppskattningen. Formuläret frågar inte efter skattepliktiga/skattefria delar, avdrag, försörjningsberättigade eller uppgifter om 13:e månadslön.", "Årsbrutto=månadsinmatning×12, annars årsbeloppet. Skatten använder motorns årliga nivåer. Arbetstagaravgifter räknas upp från SSS 5%(underlag högst PHP35 000) och PhilHealth 2,5%(högst PHP100 000); Pag-IBIG saknas.", "Vid PHP60 000 per månad ger motorn PHP720 000 i årsbrutto, PHP86 500 uppskattad skatt, PHP39 000 årsavgifter, PHP594 500 årsnetto och PHP49 541,67 per månad. Det är ett motorresultat, inte ett faktiskt löneavdrag.", "Varför kan resultatet skilja sig från lönespecifikationen?", "Modellen använder inte skattetabeller per löneperiod, klassificerar inte skattepliktiga/skattefria delar, avdrag eller krediter och saknar Pag-IBIG samt SSS-löneklasser, EC och MPF. Årsinmatning har dessutom en månadsbaserad avgiftsbegränsning; löneprecision garanteras inte."),
  },
  cs: {
    "philippines-philhealth-calculator": c("Kalkulačka PhilHealth uplatní dolní a horní hranici na měsíční základní mzdu a pojistné rozdělí rovným dílem mezi zaměstnance a zaměstnavatele. Odkazem je oznámení z roku 2025 pro Direct Contributors; jiné kategorie členství neurčuje.", "Zadejte měsíční základní mzdu v PHP. Engine používá minimum PHP10 000 a maximum PHP100 000. Do základu nepřidávejte přesčasy, provize ani příspěvky.", "Základ=min(100 000, max(10 000, měsíční základní mzda)); pojistné celkem=základ×5 %; každá část=celkem÷2. Zobrazení se zaokrouhluje na dvě desetinná místa.", "Při měsíční základní mzdě PHP30 000 činí pojistné PHP1 500, tedy PHP750 pro zaměstnance i zaměstnavatele. Jde o aritmetický příklad podle oznámení 2025.", "Zahrnují se do základu přesčasy a příspěvky?", "Oznámení z roku 2025 vylučuje z Monthly Basic Salary provize, přesčasy, příspěvky, 13. plat, bonusy a podobné položky. Kategorie členství a osobní podmínky ověřte zvlášť."),
    "philippines-pagibig-calculator": c("Kalkulačka Pag-IBIG omezuje měsíční Fund Salary na PHP10 000 a odděleně uvádí úspory zaměstnance a zaměstnavatele. Text používá limit platný od února 2024 a neurčuje výjimky členství.", "Zadejte měsíční odměnu v PHP. U obecných sazeb závisí podíl zaměstnance na tom, zda základ přesahuje PHP1 500; podíl zaměstnavatele se zobrazuje samostatně.", "Fund Salary=min(měsíční odměna, PHP10 000); zaměstnanec=základ×1 % při ≤1 500, jinak 2 %; zaměstnavatel=základ×2 %; celkem=součet obou částí.", "Při PHP30 000 měsíčně se základ omezí na PHP10 000: PHP200 zaměstnanec, PHP200 zaměstnavatel, celkem PHP400. Jde o příklad obecných sazeb.", "Strhává se podíl zaměstnavatele z mé mzdy?", "Ne. Běžný příspěvek zaměstnavatele hradí zaměstnavatel a nemá se přičítat ke srážce zaměstnance. OSVČ a dobrovolní členové mohou mít jiné povinnosti; ověřte pokyny Fondu."),
    "philippines-gross-net-salary-calculator": c("Nástroj odhaduje roční daň a vybrané příspěvky zaměstnance z hrubé mzdy a volby ročního či měsíčního období. Nenahrazuje výplatní pásku ani výpočet srážkové daně BIR.", "Zadejte hrubou mzdu v PHP a zvolte rok nebo měsíc. Měsíční částka se pro progresivní odhad daně přepočítá na rok. Formulář nezjišťuje zdanitelné/osvobozené složky, odpočty, vyživované osoby ani 13. plat.", "Roční hrubá mzda=měsíční vstup×12, jinak roční vstup. Daň používá roční pásma enginu. Příspěvky zaměstnance se anualizují podle SSS 5%(základ nejvýše PHP35 000) a PhilHealth 2,5%(nejvýše PHP100 000); Pag-IBIG chybí.", "Při PHP60 000 měsíčně engine vrátí roční hrubou mzdu PHP720 000, odhad daně PHP86 500, roční příspěvky PHP39 000, roční čistou mzdu PHP594 500 a měsíční ekvivalent PHP49 541,67. Jde o výstup enginu, ne skutečnou srážku ze mzdy.", "Proč se výsledek může lišit od výplatní pásky?", "Model nepoužívá tabulky srážek podle výplatního období, netřídí zdanitelné a osvobozené složky, odpočty či kredity a vynechává Pag-IBIG i pásma SSS, EC a MPF. Roční vstup má navíc omezení měsíčního základu příspěvků, takže přesnost výplatní agendy není zaručena."),
  },
  ro: {
    "philippines-philhealth-calculator": c("Instrumentul PhilHealth aplică un prag minim și unul maxim salariului de bază lunar, apoi împarte prima în mod egal între angajat și angajator. Referința este avizul din 2025 pentru Direct Contributors; nu determină alte categorii de membri.", "Introdu salariul de bază lunar în PHP. Motorul folosește minimum PHP10.000 și maximum PHP100.000. Nu adăuga ore suplimentare, comisioane sau indemnizații la salariul de bază.", "Bază=min(100.000, max(10.000, salariu de bază lunar)); primă totală=bază×5%; fiecare parte=total÷2. Afișarea se rotunjește la două zecimale.", "La un salariu de bază lunar de PHP30.000, prima totală este PHP1.500, câte PHP750 pentru angajat și angajator. Este un exemplu aritmetic conform avizului din 2025.", "Orele suplimentare și indemnizațiile intră în bază?", "Avizul din 2025 exclude din Monthly Basic Salary comisioanele, orele suplimentare, indemnizațiile, al 13-lea salariu, bonusurile și plățile similare. Verifică separat categoria de membru și condițiile personale."),
    "philippines-pagibig-calculator": c("Calculatorul Pag-IBIG limitează Fund Salary lunar la PHP10.000 și afișează separat economiile angajatului și ale angajatorului. Explicația folosește limita aplicabilă din februarie 2024, fără să determine excepțiile de membru.", "Introdu remunerația lunară în PHP. La ratele generale, partea angajatului depinde dacă baza depășește PHP1.500; partea angajatorului este afișată separat.", "Fund Salary=min(remunerație lunară, PHP10.000); angajat=bază×1% dacă ≤1.500, altfel 2%; angajator=bază×2%; total=suma celor două părți.", "La PHP30.000 pe lună, baza este limitată la PHP10.000: PHP200 angajat, PHP200 angajator, PHP400 total. Este un exemplu al ratelor generale.", "Partea angajatorului se reține din salariul meu?", "Nu. Contribuția obișnuită a angajatorului este responsabilitatea acestuia și nu trebuie adăugată reținerii angajatului. Persoanele independente și membrii voluntari pot avea alte obligații; consultă îndrumările Fondului."),
    "philippines-gross-net-salary-calculator": c("Instrumentul estimează impozitul anual și unele contribuții ale angajatului pe baza salariului brut și a opțiunii anual/lunar. Nu înlocuiește fluturașul de salariu sau calculul reținerii BIR.", "Introdu salariul brut în PHP și alege anual sau lunar. Valoarea lunară este anualizată pentru estimarea impozitului progresiv. Formularul nu cere componente impozabile/scutite, deduceri, persoane întreținute sau detalii despre al 13-lea salariu.", "Brut anual=intrare lunară×12 sau intrare anuală. Impozitul folosește tranșele anuale ale motorului. Contribuțiile angajatului anualizează SSS 5%(bază maximă PHP35.000) și PhilHealth 2,5%(maxim PHP100.000); Pag-IBIG este omis.", "La PHP60.000 lunar, motorul returnează brut anual PHP720.000, impozit estimat PHP86.500, contribuții anuale PHP39.000, net anual PHP594.500 și echivalent lunar PHP49.541,67. Este ieșirea motorului, nu o reținere salarială reală.", "De ce poate diferi rezultatul de fluturaș?", "Modelul nu aplică tabele de reținere pe perioade de plată, nu clasifică elemente impozabile/scutite, deduceri sau credite și omite Pag-IBIG și tranșele SSS, EC și MPF. La intrarea anuală există și o limitare a bazei lunare de contribuție; precizia de salarizare nu este garantată."),
  },
  el: {
    "philippines-philhealth-calculator": c("Το εργαλείο PhilHealth εφαρμόζει κατώτατο και ανώτατο όριο στον μηνιαίο βασικό μισθό και μοιράζει το ασφάλιστρο εξίσου σε εργαζόμενο και εργοδότη. Η αναφορά είναι η ανακοίνωση 2025 για Direct Contributors· δεν προσδιορίζει άλλες κατηγορίες μελών.", "Εισαγάγετε τον μηνιαίο βασικό μισθό σε PHP. Ο μηχανισμός χρησιμοποιεί ελάχιστο PHP10.000 και μέγιστο PHP100.000. Μην προσθέτετε υπερωρίες, προμήθειες ή επιδόματα στον βασικό μισθό.", "Βάση=min(100.000, max(10.000, μηνιαίος βασικός μισθός)); συνολικό ασφάλιστρο=βάση×5%; κάθε μερίδιο=σύνολο÷2. Η εμφάνιση στρογγυλοποιείται σε δύο δεκαδικά.", "Με μηνιαίο βασικό μισθό PHP30.000, το σύνολο είναι PHP1.500, δηλαδή PHP750 για εργαζόμενο και PHP750 για εργοδότη. Είναι αριθμητικό παράδειγμα βάσει της ανακοίνωσης 2025.", "Περιλαμβάνονται υπερωρίες και επιδόματα στη βάση;", "Η ανακοίνωση 2025 εξαιρεί προμήθειες, υπερωρίες, επιδόματα, 13ο μισθό, μπόνους και παρόμοιες πληρωμές από το Monthly Basic Salary. Ελέγξτε ξεχωριστά την κατηγορία μέλους και τις προσωπικές προϋποθέσεις."),
    "philippines-pagibig-calculator": c("Ο υπολογιστής Pag-IBIG περιορίζει το μηνιαίο Fund Salary σε PHP10.000 και εμφανίζει χωριστά την αποταμίευση εργαζομένου και εργοδότη. Το κείμενο χρησιμοποιεί το όριο από τον Φεβρουάριο 2024, χωρίς να κρίνει εξαιρέσεις μέλους.", "Εισαγάγετε μηνιαία αμοιβή σε PHP. Με τους γενικούς συντελεστές, το μερίδιο εργαζομένου εξαρτάται από το αν η βάση υπερβαίνει τις PHP1.500· το μερίδιο εργοδότη εμφανίζεται χωριστά.", "Fund Salary=min(μηνιαία αμοιβή, PHP10.000); εργαζόμενος=βάση×1% αν ≤1.500, αλλιώς 2%; εργοδότης=βάση×2%; σύνολο=άθροισμα μεριδίων.", "Με PHP30.000 τον μήνα, η βάση περιορίζεται σε PHP10.000: PHP200 εργαζόμενος, PHP200 εργοδότης, PHP400 συνολικά. Είναι παράδειγμα των γενικών συντελεστών.", "Παρακρατείται από τον μισθό μου το μερίδιο του εργοδότη;", "Όχι. Η συνήθης εργοδοτική εισφορά είναι ευθύνη του εργοδότη και δεν πρέπει να προστεθεί στην παρακράτηση εργαζομένου. Αυτοαπασχολούμενοι και εθελοντικά μέλη μπορεί να έχουν άλλες υποχρεώσεις· δείτε τις οδηγίες του Ταμείου."),
    "philippines-gross-net-salary-calculator": c("Το εργαλείο εκτιμά τον ετήσιο φόρο και ορισμένες εισφορές εργαζομένου από τον μικτό μισθό και την επιλογή ετήσιας ή μηνιαίας περιόδου. Δεν αντικαθιστά εκκαθαριστικό μισθοδοσίας ή υπολογισμό παρακράτησης BIR.", "Εισαγάγετε μικτό μισθό σε PHP και επιλέξτε ετήσια ή μηνιαία περίοδο. Το μηνιαίο ποσό αναγάγεται σε ετήσιο για την προοδευτική εκτίμηση φόρου. Δεν ζητούνται φορολογητέα/απαλλασσόμενα στοιχεία, εκπτώσεις, εξαρτώμενα μέλη ή στοιχεία 13ου μισθού.", "Ετήσιος μικτός=μηνιαία είσοδος×12 ή ετήσια είσοδος. Ο φόρος χρησιμοποιεί τις ετήσιες κλίμακες του μηχανισμού. Οι εισφορές εργαζομένου αναγάγονται από SSS 5%(βάση έως PHP35.000) και PhilHealth 2,5%(έως PHP100.000)· το Pag-IBIG δεν περιλαμβάνεται.", "Με PHP60.000 τον μήνα, ο μηχανισμός δίνει ετήσιο μικτό PHP720.000, εκτιμώμενο φόρο PHP86.500, ετήσιες εισφορές PHP39.000, ετήσιο καθαρό PHP594.500 και μηνιαίο ισοδύναμο PHP49.541,67. Είναι έξοδος του μηχανισμού, όχι πραγματική παρακράτηση μισθοδοσίας.", "Γιατί μπορεί να διαφέρει από το εκκαθαριστικό;", "Το μοντέλο δεν εφαρμόζει πίνακες παρακράτησης ανά περίοδο, δεν ταξινομεί φορολογητέα/απαλλασσόμενα ποσά, εκπτώσεις ή πιστώσεις και παραλείπει Pag-IBIG και κλίμακες SSS, EC και MPF. Η ετήσια είσοδος έχει επίσης περιορισμό μηνιαίας βάσης εισφορών, επομένως δεν διασφαλίζεται ακρίβεια μισθοδοσίας."),
  },
};
